const QUESTIONS = [
  {"id": "T3-001", "test": "T3", "set": "T3-ucitel", "topic": "Test 3 – zadání", "q": "Jaké vzdálenosti odpovídá hodnota −30 mm při použití konstanty hranolu −30 mm u našich odrazných hranolů (k jaké části odrazného hranolu)?", "a": "Vzdálenosti od závitu hranolu ke svislé ose držáku hranolu (k ose výtyčky / tyče).", "wrong": ["Vzdálenosti od přední stěny skla hranolu k jeho středu", "Tloušťce skla hranolu", "Vzdálenosti od středu hranolu ke špičce výtyčky"], "note": "Spolužákova odpověď v tomto znění dostala od učitele plný bod. Konstanta hranolu patří mezi korekce měřených délek (přednáška 5).", "weak": false},
  {"id": "T3-002", "test": "T3", "set": "T3-ucitel", "topic": "Test 3 – zadání", "q": "Z jakých dílčích korekcí se skládají matematické korekce měřených délek při práci v S-JTSK?", "a": "Z redukce na nulový horizont (do nulové hladiny) a z redukce ze zobrazení (Křovákovo zobrazení).", "wrong": ["Z korekce z teploty a tlaku vzduchu", "Z konstanty hranolu a adiční konstanty", "Z redukce o střešní přesah a doměrku"], "note": "Přednáška 5: v místním systému (plán) se nezavádějí, v S-JTSK (konformní zobrazení) ano. Spolužák dostal 0,75 b. Piš oba názvy přesně jako na slajdu.", "weak": false},
  {"id": "T3-003", "test": "T3", "set": "T3-ucitel", "topic": "Test 3 – zadání", "q": "Jak se zaměřují křivkové prvky polohopisu v případě obecné křivky?", "a": "Obecné křivky se nahrazují úsečkami. Jejich délka se volí tak, aby se žádný bod na úsečce neodchýlil od skutečného průběhu o více než 0,7·uxy pro danou třídu přesnosti.", "wrong": ["Třemi body: začátek, střed a konec oblouku", "Středem a poloměrem", "Třemi body rovnoměrně rozloženými po obvodu"], "note": "Kružnicový oblouk = 3 body (začátek, střed, konec); kružnice = 3 body po obvodu nebo střed a poloměr.", "weak": false},
  {"id": "T3-004", "test": "T3", "set": "T3-ucitel", "topic": "Test 3 – zadání", "q": "Jak máme pro účely cvičení stanovenu mezní odchylku pro opravu orientačního směru?", "a": "0,04 gon (rozdíl směrníků vypočtených ze souřadnic minus rozdíl naměřených vodorovných směrů).", "wrong": ["0,02 gon", "0,4 gon", "2,5/d gon"], "note": "Přednáška 4, mezní odchylky pro předmět Mapování 1. Pozor: reálně závisí na délkách orientací.", "weak": false},
  {"id": "T3-005", "test": "T3", "set": "T3-ucitel", "topic": "Test 3 – zadání", "q": "V jakém rozmezí musí být úhel na určovaném volném polárním stanovisku (na dva dané body)?", "a": "V rozmezí 30 gon až 170 gon.", "wrong": ["20 gon až 180 gon", "50 gon až 150 gon", "30° až 170°"], "note": "Stejně i u protínání ze směrů nebo z délek.", "weak": false},
  {"id": "T3-006", "test": "T3", "set": "T3-ucitel", "topic": "Test 3 – zadání", "q": "Jak exportujeme protokol měření totální stanicí v přístroji s Trimble Access, pokud máme nastavenou práci se zápornými souřadnicemi a v exportovaném protokolu je chceme mít kladné (jaké zvolíme exportní protokoly)?", "a": "Zvolíme exportní protokol s kladnými souřadnicemi X (Jih), Y (Západ), tedy S-JTSK EPSG:5513 – v Trimble Access protokol „CZ Katastr – protokol měření“.", "wrong": ["Exportujeme v souřadnicích S-JTSK EPSG:5514 (Sever, Východ)", "Změníme v jobu grid na jižní a znovu měříme", "Kladné souřadnice v protokolu získat nejde"], "note": "NEJISTÉ: na slajdu je jen obrázek s nastavením. Spolužák napsal „při exportu volíme SV“ a dostal 0,75 b. Ověř si na cvičení přesný název protokolu.", "weak": false},
  {"id": "T3-007", "test": "T3", "set": "T3-ucitel", "topic": "Test 3 – zadání", "q": "Jak je při vyrovnání sítě testován poměr apriorní a aposteriorní jednotkové střední chyby (jaký interval hodnot je přijatelný)?", "a": "Poměr se má co nejvíce blížit hodnotě 1 (v intervalu spolehlivosti). Přijatelný je interval spolehlivosti (zpravidla 95 %).", "wrong": ["Poměr má být co nejblíže 0", "Poměr má být větší než 2", "Poměr se netestuje, testují se jen opravy"], "note": "Přednáška 6. Spolužák: „v ideálním případě 1, přijatelný je 95 %“. Když poměr nesedí, upraví se apriorní přesnosti (ale musí být reálné).", "weak": false},
  {"id": "T3-008", "test": "T3", "set": "T3-ucitel", "topic": "Test 3 – zadání", "q": "Jak nastavíme v přístroji s Trimble Access práci se zápornými souřadnicemi S-JTSK – EPSG:5514?", "a": "V nastavení jobu → souřadnicový systém → grid (souřadnice) zvolíme orientaci SV (Sever, Východ) a zrušíme (deaktivujeme) jižní grid.", "wrong": ["Zvolíme orientaci JZ (Jih, Západ)", "Nastavíme jen měřítkový faktor", "Zadáme konstantu hranolu −30 mm"], "note": "Spolužák dostal plný bod. EPSG:5514 = záporné souřadnice Y (Sever) X (Východ).", "weak": false},
  {"id": "T3-009", "test": "T3", "set": "T3-ucitel", "topic": "Test 3 – zadání", "q": "Jak nastavíme v přístroji s Trimble Access aplikaci matematických korekcí v průběhu měření?", "a": "V nastavení jobu → souřadnicový systém → měřítko → pouze měřítkový faktor; nebo zvolíme systém Czech Republic, Křovákovo zobrazení a zadáme průměrnou výšku lokality.", "wrong": ["V nastavení korekcí zadáme teplotu a tlak", "Zapneme konstantu hranolu", "Matematické korekce v Trimble Access nastavit nejde"], "note": "Spolužák dostal plný bod. Pozor na kombinace – korekce lze zavést v přístroji, při exportu nebo při importu do výpočetního SW, ale jen jednou.", "weak": false},
  {"id": "T3-010", "test": "T3", "set": "T3-ucitel", "topic": "Test 3 – zadání", "q": "Jak je omezena maximální délka rajonu?", "a": "Délka rajonu může být nejvýše 1000 m a přitom nejvýše o 1/3 větší než délka měřické přímky (její delší části, je-li výchozí bod mezilehlý), na kterou je rajon připojen, nebo nesmí být větší než délka k nejvzdálenějšímu orientačnímu bodu.", "wrong": ["Nejvýše 250 m", "Nejvýše 2000 m", "Nejvýše 1,5× délka nejvzdálenější orientace"], "note": "Spolužák napsal jen 1000 m a volný pořad 250 m a dostal 0,75 b. Piš celé pravidlo.", "weak": false},
  {"id": "T3-011", "test": "T3", "set": "T3-ucitel", "topic": "Test 3 – zadání", "q": "Jak postupujeme při výpočtu u vícenásobného určení podrobného bodu?", "a": "Nejsou-li překročeny mezní odchylky, výsledné souřadnice se vypočtou jednoduchým aritmetickým průměrem. Obecný (vážený) průměr jen tehdy, jsou-li váhy odborně zdůvodněny. Překročení mezních odchylek se analyzuje a chyby se opraví; odchylky se uvedou v protokolu.", "wrong": ["Ponechá se první určení", "Vezme se určení z nejbližšího stanoviska", "Vždy se použije vážený průměr podle délek"], "note": "Otázka z druhé verze Testu 3 (z projektoru).", "weak": false},
  {"id": "T3-012", "test": "T3", "set": "T3-tip", "topic": "Metody podrobného měření", "q": "Jaké jsou metody podrobného měření (číselné a grafické)?", "a": "Číselná (polární, ortogonální, protínání…) a grafická (historie).", "wrong": ["Jen polární a GNSS", "Analogová a digitální", "Statická a kinematická"], "note": "", "weak": false},
  {"id": "T3-013", "test": "T3", "set": "T3-tip", "topic": "Metody podrobného měření", "q": "Jaké skupiny metod podrobného měření uvádí přednáška?", "a": "Geodetické metody, fotogrammetrické metody, laserové skenování (pozemní TLS, letecké ALS) a mobilní mapování.", "wrong": ["Polární, ortogonální a nivelační", "Jen GNSS a totální stanice", "Grafické, číselné a výpočetní"], "note": "", "weak": false},
  {"id": "T3-014", "test": "T3", "set": "T3-tip", "topic": "Metody podrobného měření", "q": "Jakými metodami se obvykle zaměřují podrobné body?", "a": "Polární metodou (tachymetrie) nebo technologií GNSS.", "wrong": ["Ortogonální metodou a pásmem", "Protínáním zpět", "Konstrukčními oměrnými"], "note": "", "weak": false},
  {"id": "T3-015", "test": "T3", "set": "T3-tip", "topic": "Metody podrobného měření", "q": "Kdy se použijí ostatní geodetické metody podrobného měření?", "a": "Pro body, které není možné nebo účelné určit polární metodou nebo GNSS (nepřístupné body, výstupky a rozhraní na budovách, stísněná zástavba apod.).", "wrong": ["Vždy pro body na zpevněném povrchu", "Jen pro výškopis", "Jen při mapování v 1. třídě přesnosti"], "note": "", "weak": false},
  {"id": "T3-016", "test": "T3", "set": "T3-tip", "topic": "Metody podrobného měření", "q": "Kterým předpisem se řídí určování polohy podrobných bodů technologií GNSS?", "a": "Vyhláškou č. 31/1995 Sb., příloha 9 (Technické požadavky měření a výpočty bodů určovaných technologií GNSS).", "wrong": ["ČSN 01 3410", "Katastrální vyhláškou, příloha 13", "ČSN 01 3411"], "note": "", "weak": false},
  {"id": "T3-017", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Jaké metody měření GNSS lze podle přílohy 9 využít?", "a": "Měření v reálném čase i měření s následným zpracováním; při následném zpracování statické metody (v klidu) i kinematické metody (za pohybu).", "wrong": ["Jen statické metody", "Jen RTK", "Jen postprocessing"], "note": "", "weak": false},
  {"id": "T3-018", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Kolik záznamů musí nejméně obsahovat měření v reálném čase a kinematické metody GNSS?", "a": "Nejméně 5 záznamů.", "wrong": ["Nejméně 3 záznamy", "Nejméně 10 záznamů", "Nejméně 1 záznam"], "note": "", "weak": false},
  {"id": "T3-019", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Jaké řešení GNSS lze použít pro další zpracování?", "a": "Jen řešení, kde byly ambiguity určeny jako celá čísla (fixované řešení).", "wrong": ["I plovoucí (float) řešení", "Jen řešení s PDOP pod 2", "Jen řešení z permanentní stanice"], "note": "", "weak": false},
  {"id": "T3-020", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Kdy nelze použít virtuální referenční stanici sítě permanentních stanic?", "a": "Když je poskytnuta na větší vzdálenost od nejbližší permanentní stanice sítě, než uvádí dokumentace sítě (nebo praxe).", "wrong": ["Nikdy, VRS lze použít vždy", "Když je PDOP menší než 7", "Když měříme déle než 1 hodinu"], "note": "", "weak": false},
  {"id": "T3-021", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Z čeho musí být určena poloha bodu technologií GNSS?", "a": "Ze dvou nezávislých výsledků měření GNSS, nebo z jednoho výsledku GNSS a jednoho výsledku klasickou metodou.", "wrong": ["Z jednoho měření s 5 záznamy", "Ze tří měření ve stejném čase", "Z jednoho měření s fixovaným řešením"], "note": "", "weak": false},
  {"id": "T3-022", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Jak musí být provedeno opakované měření GNSS?", "a": "Nezávisle, při nezávislém postavení družic – nesmí být v čase v intervalu ⟨−1 + n·k; n·k + 1⟩ hodin vůči ověřovanému měření.", "wrong": ["Hned po prvním měření na stejném bodě", "Kdykoli, stačí jiná anténa", "Jen ve stejný den"], "note": "", "weak": false},
  {"id": "T3-023", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Jaká je hodnota n v pravidle pro nezávislé opakované měření GPS a GLONASS?", "a": "GPS-NAVSTAR n = 23,9333 h (23 h 56 min), GLONASS n = 22,5 h (22 h 30 min).", "wrong": ["GPS 24 h, GLONASS 12 h", "GPS 12 h, GLONASS 24 h", "Obě 23 h 56 min"], "note": "", "weak": false},
  {"id": "T3-024", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Co znamená k v intervalu ⟨−1 + n·k; n·k + 1⟩ hodin?", "a": "Počet dní; nabývá jen nezáporných celých čísel.", "wrong": ["Počet družic", "Koeficient přesnosti 1 nebo 2", "Počet záznamů"], "note": "", "weak": false},
  {"id": "T3-025", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Jaké omezení platí pro ověřování, je-li GDOP nebo PDOP větší než 7,0?", "a": "Takový výsledek nelze ověřit jiným výsledkem s GDOP/PDOP > 7,0, je-li čas ověřujícího měření v intervalu ⟨−3 + n·k; n·k + 3⟩ hodin.", "wrong": ["Výsledek se vždy vyřadí", "Stačí ho změřit podruhé hned", "Platí jen pro GLONASS"], "note": "", "weak": false},
  {"id": "T3-026", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Jaké podmínky platí, určuje-li se poloha s následným zpracováním z jediného měření GNSS?", "a": "Výška antény zjištěna dvěma nezávislými způsoby (nebo před a po měření); při době měření pod 1 h GDOP/PDOP nesmí překročit 7,0; poloha nesmí být určena jen z VRS (nebo kombinace VRS a permanentní stanice téže sítě).", "wrong": ["Stačí jedna výška antény a PDOP pod 10", "Měření musí trvat aspoň 24 h", "Musí se použít jen VRS"], "note": "", "weak": false},
  {"id": "T3-027", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Čím lze u pomocných a podrobných bodů nahradit opakované měření GNSS?", "a": "Ověřením vzájemné polohy nově určených bodů nebo polohy vůči stávajícímu bodu vhodným počtem kontrolně měřených délek, úhlů nebo jejich kombinací.", "wrong": ["Delší dobou měření", "Měřením jinou anténou", "Ničím, opakování je vždy nutné"], "note": "", "weak": false},
  {"id": "T3-028", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Který kontrolní prvek nelze použít pro ověření polohy bodu určeného GNSS?", "a": "Délku mezi body, které nebyly určeny nezávisle (také úhel v trojúhelníku se dvěma nezávisle neurčenými body mimo uzávěr a uzávěr obrazce z nezávisle neurčených bodů).", "wrong": ["Délku na bod bodového pole", "Úhel mezi body bodového pole", "Oměrnou míru k ověřenému bodu"], "note": "", "weak": false},
  {"id": "T3-029", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Jak lze připojit měření do ETRS v epoše 1989.0?", "a": "Měřením na nejméně dvou připojovacích bodech, nezávislou dvojicí měření na jednom ověřeném bodě, nebo využitím schválené permanentní stanice (popř. VRS takové sítě).", "wrong": ["Jen měřením na jednom bodě", "Jen transformací v kanceláři", "Odhadem z mapy"], "note": "", "weak": false},
  {"id": "T3-030", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Kdy lze použít zpřesněnou globální transformaci ETRS89 → S-JTSK bez identických bodů?", "a": "Pro práce, kde stačí přesnost mxy = 0,06 m, se schváleným programem a podle návodu.", "wrong": ["Pro všechny práce bez omezení", "Jen pro mxy = 0,02 m", "Jen pro výšky"], "note": "", "weak": false},
  {"id": "T3-031", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Kolik identických bodů je třeba při výpočtu místních transformačních parametrů?", "a": "Nejméně čtyři.", "wrong": ["Nejméně dva", "Nejméně tři", "Nejméně šest"], "note": "", "weak": false},
  {"id": "T3-032", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Jaké jsou vzdálenostní podmínky pro identické body místní transformace?", "a": "Rovnoměrné rozložení, průměrná vzdálenost sousedních identických bodů nejvýše 5 km a žádná vzdálenost větší než 8 km.", "wrong": ["Průměr 10 km, max. 20 km", "Průměr 1 km, max. 2 km", "Bez omezení"], "note": "", "weak": false},
  {"id": "T3-033", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Jaký nejmenší vnitřní úhel smí mít obvodový polygon identických bodů?", "a": "20°.", "wrong": ["30 gon", "10°", "45°"], "note": "", "weak": false},
  {"id": "T3-034", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Jak daleko vně obrazce identických bodů smí ležet určovaný bod?", "a": "Nejvýše 1/10 délky nejbližší spojnice dvou sousedních identických bodů.", "wrong": ["Nejvýše 1/3 délky spojnice", "Nejvýše 1 km", "Vůbec nesmí ležet vně"], "note": "", "weak": false},
  {"id": "T3-035", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Co se udělá, když transformací zjištěná odchylka na identickém bodě překročí povolenou hodnotu?", "a": "Bod se z transformace vyloučí a zvolí se jiný, nebo se oprávněnost doloží ověřením polohy bodu (a případně jeho souřadnic).", "wrong": ["Odchylka se rozdělí na ostatní body", "Bod se použije s menší vahou", "Transformace se nepočítá"], "note": "", "weak": false},
  {"id": "T3-036", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Jaké podmínky musí splňovat souřadnice identických bodů pro místní transformaci?", "a": "Získány měřením nebo převzaty z platných geodetických údajů, s přesností vyšší nebo stejnou než požadovaná, ve shodném geocentrickém systému (u WGS84 ve stejné realizaci).", "wrong": ["Mohou být odečteny z mapy", "Stačí přesnost horší než u určovaných bodů", "Mohou být v různých realizacích WGS84"], "note": "", "weak": false},
  {"id": "T3-037", "test": "T3", "set": "T3-tip", "topic": "Terestrická měření – vyhláška, příloha 10", "q": "Pro jakou přesnost platí podmínky terestrického měření v příloze 10 (bod 10.2)?", "a": "Pro výsledky, kde stačí přesnost mxy = 0,14 m.", "wrong": ["mxy = 0,06 m", "mxy = 0,02 m", "mxy = 0,26 m"], "note": "", "weak": false},
  {"id": "T3-038", "test": "T3", "set": "T3-tip", "topic": "Terestrická měření – vyhláška, příloha 10", "q": "Jaké body se použijí, je-li podrobné měření připojeno jen na dva body?", "a": "Dva body polohových bodových polí nebo pomocné body; u volného polárního stanoviska se na oba změří vodorovné směry i délky.", "wrong": ["Dva podrobné body bez ověření", "Jeden bod bodového pole a jeden podrobný", "Dva body z mapy"], "note": "", "weak": false},
  {"id": "T3-039", "test": "T3", "set": "T3-tip", "topic": "Terestrická měření – vyhláška, příloha 10", "q": "Na kolik bodů se provede orientace na stanovisku?", "a": "Vždy nejméně na dva body polohových bodových polí nebo na pomocné body.", "wrong": ["Stačí jeden bod", "Nejméně na tři body", "Nejméně na pět bodů"], "note": "", "weak": false},
  {"id": "T3-040", "test": "T3", "set": "T3-tip", "topic": "Terestrická měření – vyhláška, příloha 10", "q": "Co když nelze zaměřit více než jeden orientační směr?", "a": "Použije se oboustranně připojený a oboustranně orientovaný polygonový pořad, nebo se orientace ověří kontrolním zaměřením podrobného bodu určeného z jiného stanoviska.", "wrong": ["Měří se bez kontroly", "Stanovisko se zruší", "Použije se jen GNSS"], "note": "", "weak": false},
  {"id": "T3-041", "test": "T3", "set": "T3-tip", "topic": "Terestrická měření – vyhláška, příloha 10", "q": "Jak se orientuje měření připojené jen na podrobné body?", "a": "Nejméně na dva v terénu jednoznačně identifikovatelné podrobné body.", "wrong": ["Na jeden podrobný bod", "Na sever podle buzoly", "Nelze orientovat"], "note": "", "weak": false},
  {"id": "T3-042", "test": "T3", "set": "T3-tip", "topic": "Terestrická měření – vyhláška, příloha 10", "q": "Jak dlouhý smí být polygonový pořad z pomocných bodů?", "a": "Nejvýše 2000 m.", "wrong": ["Nejvýše 1000 m", "Nejvýše 250 m", "Nejvýše 5000 m"], "note": "", "weak": false},
  {"id": "T3-043", "test": "T3", "set": "T3-tip", "topic": "Terestrická měření – vyhláška, příloha 10", "q": "Jak je omezen volný polygonový pořad?", "a": "Může být nejvýše dvakrát lomený (nejvýše 3 navazující rajony) a nesmí být delší než 250 m.", "wrong": ["Max. 5 stran a 1000 m", "Max. 2 strany a 500 m", "Bez omezení lomu, max. 250 m"], "note": "", "weak": false},
  {"id": "T3-044", "test": "T3", "set": "T3-tip", "topic": "Terestrická měření – vyhláška, příloha 10", "q": "O kolik lze jednoduchými pomůckami prodloužit měřickou přímku?", "a": "Nejvýše o 1/3 její délky.", "wrong": ["O 1/2 délky", "O 3/4 délky", "O 30 m"], "note": "", "weak": false},
  {"id": "T3-045", "test": "T3", "set": "T3-tip", "topic": "Terestrická měření – vyhláška, příloha 10", "q": "Jak dlouhá smí být kolmice u ortogonální metody?", "a": "Nejvýše 3/4 délky příslušné měřické přímky a nejvýše 30 m.", "wrong": ["1/2 délky přímky a 50 m", "1/3 délky přímky a 10 m", "Bez omezení"], "note": "", "weak": false},
  {"id": "T3-046", "test": "T3", "set": "T3-tip", "topic": "Přesnost podrobného měření", "q": "Jakými dálkoměry se měří délky při podrobném měření?", "a": "Dálkoměry s optickými odraznými systémy; s pasivním odrazem jen výjimečně (nepřístupný bod, kontrolní měření již zaměřeného bodu).", "wrong": ["Vždy bez hranolu", "Jen pásmem", "Jen GNSS"], "note": "", "weak": false},
  {"id": "T3-047", "test": "T3", "set": "T3-tip", "topic": "Přesnost podrobného měření", "q": "S jakou přesností se měří a registrují délky?", "a": "Na 0,01 m.", "wrong": ["Na 0,001 m", "Na 0,1 m", "Na 0,05 m"], "note": "", "weak": false},
  {"id": "T3-048", "test": "T3", "set": "T3-tip", "topic": "Přesnost podrobného měření", "q": "Kdy se pro měření délek použije pásmo a jaké podmínky musí splňovat?", "a": "Pro krátké délky (zpravidla na jeden klad); musí jít o kalibrované měřidlo s atestem (zákon č. 505/1990 Sb. o metrologii).", "wrong": ["Pro délky nad 100 m, bez kalibrace", "Nikdy", "Jen pro výšky"], "note": "", "weak": false},
  {"id": "T3-049", "test": "T3", "set": "T3-tip", "topic": "Přesnost podrobného měření", "q": "O jaké redukce se opravují měřené délky a kdy se zavádí redukce do zobrazovací roviny S-JTSK?", "a": "O fyzikální (teplota, tlak), matematické (do vodorovné roviny, z nadmořské výšky) a o redukci do zobrazovací roviny S-JTSK, pokud jejich součet přesáhne 0,02 m.", "wrong": ["Jen o konstantu hranolu", "Jen o fyzikální, vždy", "Redukce se nezavádějí"], "note": "", "weak": false},
  {"id": "T3-050", "test": "T3", "set": "T3-tip", "topic": "Přesnost podrobného měření", "q": "Kolikrát se měří délky v měřické síti a kolikrát na podrobné body?", "a": "V měřické síti vždy 2×, na podrobné body 1×.", "wrong": ["Obojí 1×", "Obojí 2×", "Síť 3×, podrobné 2×"], "note": "", "weak": false},
  {"id": "T3-051", "test": "T3", "set": "T3-tip", "topic": "Přesnost podrobného měření", "q": "Jaká kontrola se dělá na každém stanovisku?", "a": "Zaměří se nejméně jeden podrobný bod určený též z jiného stanoviska.", "wrong": ["Změří se teplota", "Změří se výška stroje dvakrát", "Nic, kontrola je až ve výpočtu"], "note": "", "weak": false},
  {"id": "T3-052", "test": "T3", "set": "T3-tip", "topic": "Přesnost podrobného měření", "q": "S jakou přesností se měří a registrují směry?", "a": "Alespoň na 0,0010 gon.", "wrong": ["Na 0,01 gon", "Na 0,1 mgon", "Na 1 cc"], "note": "", "weak": false},
  {"id": "T3-053", "test": "T3", "set": "T3-tip", "topic": "Přesnost podrobného měření", "q": "V kolika polohách dalekohledu se měří podrobné body a jak měřická síť?", "a": "Podrobné body jen v 1. poloze; u měřické sítě zvážit 1 skupinu a trojpodstavcovou soupravu.", "wrong": ["Obojí ve 2 polohách", "Podrobné ve 2 polohách, síť v 1.", "Obojí jen v 1. poloze bez skupin"], "note": "", "weak": false},
  {"id": "T3-054", "test": "T3", "set": "T3-tip", "topic": "Přesnost podrobného měření", "q": "Jaká je mezní odchylka rozdílu dvojího měření délky v měřické síti?", "a": "0,001·√d + 0,02 m (d v metrech).", "wrong": ["0,004·√d + 0,04 m", "0,03 m", "0,06 m"], "note": "", "weak": false},
  {"id": "T3-055", "test": "T3", "set": "T3-tip", "topic": "Přesnost podrobného měření", "q": "Jaká je mezní odchylka dvojího měření převýšení v měřické síti?", "a": "0,03 m.", "wrong": ["0,02 m", "0,06 m", "0,1 m"], "note": "", "weak": false},
  {"id": "T3-056", "test": "T3", "set": "T3-tip", "topic": "Přesnost podrobného měření", "q": "Jaká je mezní odchylka oměrných měr mezi jednoznačně identifikovatelnými podrobnými body?", "a": "0,06 m.", "wrong": ["0,03 m", "0,02 m", "0,14 m"], "note": "", "weak": false},
  {"id": "T3-057", "test": "T3", "set": "T3-tip", "topic": "Přesnost podrobného měření", "q": "Jaké jsou mezní odchylky pro směry na pomocné body a na jednoznačně identifikovatelné podrobné body?", "a": "Pomocné body v síti 2,5/d gon, jednoznačně identifikovatelné podrobné body 4/d gon (d v metrech).", "wrong": ["Obojí 0,04 gon", "Pomocné 4/d, podrobné 2,5/d gon", "Obojí 0,001 gon"], "note": "", "weak": false},
  {"id": "T3-058", "test": "T3", "set": "T3-tip", "topic": "Přesnost podrobného měření", "q": "Jaká je mezní polohová odchylka uzávěru pomocného polygonového pořadu (a délky měřické přímky)?", "a": "Δp = 0,004·√d + 0,04 m.", "wrong": ["0,001·√d + 0,02 m", "0,005·√n + 2 gon", "0,06 m"], "note": "", "weak": false},
  {"id": "T3-059", "test": "T3", "set": "T3-tip", "topic": "Přesnost podrobného měření", "q": "Jaká je mezní úhlová odchylka uzávěru pomocného polygonového pořadu?", "a": "Δω = 0,005·√(n + 2) gon, kde n je počet vrcholových úhlů v pořadu včetně připojovacích bodů.", "wrong": ["Δω = 0,04 gon", "Δω = 0,004·√d + 0,04 gon", "Δω = 2,5/d gon"], "note": "", "weak": false},
  {"id": "T3-060", "test": "T3", "set": "T3-tip", "topic": "Přesnost podrobného měření", "q": "Pro jakou třídu přesnosti platí uvedené mezní odchylky podrobného měření?", "a": "Pro požadavky 2. třídy přesnosti dle ČSN 01 3410.", "wrong": ["Pro 1. třídu", "Pro 3. třídu", "Pro katastrální kód kvality 5"], "note": "", "weak": false},
  {"id": "T3-061", "test": "T3", "set": "T3-tip", "topic": "Mezní odchylky pro předmět Mapování 1", "q": "Jaká je mezní odchylka na pomocném bodě v souřadnici (rozdíl dvojího nezávislého určení)?", "a": "0,5·uxy.", "wrong": ["1,7·uxy", "0,7·uxy", "uxy/4"], "note": "", "weak": false},
  {"id": "T3-062", "test": "T3", "set": "T3-tip", "topic": "Mezní odchylky pro předmět Mapování 1", "q": "Jak se počítá mezní odchylka ud mezi přímo měřenou délkou dvou podrobných bodů a délkou ze souřadnic?", "a": "ud = 1,5·uxy·(d + 12)/(d + 20) [m].", "wrong": ["ud = 0,004·√d + 0,04", "ud = 2·uxy", "ud = 0,06 m"], "note": "", "weak": false},
  {"id": "T3-063", "test": "T3", "set": "T3-tip", "topic": "Mezní odchylky pro předmět Mapování 1", "q": "Co znamená d ve vzorci Δp = 0,004·√d + 0,04 m?", "a": "Délku měřické přímky, spojnice kontrolovaných bodů nebo součet délek v pomocném polygonovém pořadu v metrech.", "wrong": ["Počet vrcholů pořadu", "Délku nejdelší strany v km", "Vzdálenost od stanoviska k orientaci"], "note": "", "weak": false},
  {"id": "T3-064", "test": "T3", "set": "T3-tip", "topic": "Mezní odchylky pro předmět Mapování 1", "q": "Jak je v Gromě nastavena tolerance „Rozdíl ve dvakrát měřené délce“ v sadě Mapování 1?", "a": "0.001*SQRT(s) + 0.02.", "wrong": ["0.004*SQRT(s) + 0.04", "0.0400", "50.00*SQRT(n + 2)"], "note": "", "weak": false},
  {"id": "T3-065", "test": "T3", "set": "T3-tip", "topic": "Mezní odchylky pro předmět Mapování 1", "q": "Jaký minimální úhel protnutí u průsečíku a protínání je nastaven v toleranci Mapování 1?", "a": "30 gon (30.0000).", "wrong": ["20 gon", "50 gon", "10 gon"], "note": "", "weak": false},
  {"id": "T3-066", "test": "T3", "set": "T3-tip", "topic": "Mezní odchylky pro předmět Mapování 1", "q": "Jaká maximální oprava orientace je nastavena v toleranci Mapování 1?", "a": "0,0400 gon.", "wrong": ["0,0200 gon", "0,0040 gon", "0,4000 gon"], "note": "", "weak": false},
  {"id": "T3-067", "test": "T3", "set": "T3-tip", "topic": "Mezní odchylky pro předmět Mapování 1", "q": "Jaká maximální střední chyba transformačního klíče je nastavena v toleranci Mapování 1?", "a": "0,04.", "wrong": ["0,14", "0,02", "0,4"], "note": "", "weak": false},
  {"id": "T3-068", "test": "T3", "set": "T3-tip", "topic": "Síť pomocných měřických bodů", "q": "K čemu slouží síť pomocných měřických bodů a v jaké hustotě se volí?", "a": "Doplňuje polohová bodová pole pro podrobné měření; volí se v hustotě nezbytné pro zaměření podrobných bodů.", "wrong": ["Nahrazuje bodové pole", "Volí se vždy po 100 m", "Slouží jen pro výškopis"], "note": "", "weak": false},
  {"id": "T3-069", "test": "T3", "set": "T3-tip", "topic": "Síť pomocných měřických bodů", "q": "Jakými způsoby se určují pomocné body?", "a": "Staničením na měřických přímkách, rajony, pomocnými polygonovými pořady, protínáním ze směrů (popř. z délek), jako volné polární stanovisko, technologií GNSS a plošnými sítěmi.", "wrong": ["Jen polární metodou", "Jen GNSS", "Odečtem z mapy"], "note": "", "weak": false},
  {"id": "T3-070", "test": "T3", "set": "T3-tip", "topic": "Síť pomocných měřických bodů", "q": "Jak se pomocné body označují?", "a": "Dočasně – dřevěným kolíkem, kovovou trubkou, hřebem, vyrytým křížkem apod.", "wrong": ["Vždy žulovým mezníkem", "Jen barvou na asfaltu", "Neoznačují se"], "note": "", "weak": false},
  {"id": "T3-071", "test": "T3", "set": "T3-tip", "topic": "Síť pomocných měřických bodů", "q": "Kdy se pomocné body zaměřují?", "a": "Před zahájením podrobného měření nebo současně s ním (zpravidla současně).", "wrong": ["Až po podrobném měření", "Jen v zimě", "Až při zpracování"], "note": "", "weak": false},
  {"id": "T3-072", "test": "T3", "set": "T3-tip", "topic": "Síť pomocných měřických bodů", "q": "Jak dlouhá smí být měřická přímka?", "a": "Nejvýše 2000 m.", "wrong": ["Nejvýše 1000 m", "Nejvýše 250 m", "Nejvýše 30 m"], "note": "", "weak": false},
  {"id": "T3-073", "test": "T3", "set": "T3-tip", "topic": "Síť pomocných měřických bodů", "q": "Čím lze určit body měřické sítě technologií GNSS a jak se kontrolují?", "a": "RTK nebo měřením s následným zpracováním (postprocessing); kontrola opakovaným určením GNSS nebo jinou metodou.", "wrong": ["Jen statikou, bez kontroly", "Jen VRS bez opakování", "GNSS se pro síť nepoužívá"], "note": "", "weak": false},
  {"id": "T3-074", "test": "T3", "set": "T3-tip", "topic": "Síť pomocných měřických bodů", "q": "Jaké minimální měření vyžaduje pevné polární stanovisko?", "a": "2 směry + 1 délka (orientace nejméně na 2 body, délka nejméně na jeden; vždy raději víc).", "wrong": ["1 směr + 1 délka", "2 směry + 2 délky", "3 směry bez délky"], "note": "", "weak": false},
  {"id": "T3-075", "test": "T3", "set": "T3-tip", "topic": "Síť pomocných měřických bodů", "q": "Kdy lze u pevného stanoviska neměřit délku na orientační bod?", "a": "Jen při orientaci na dva trvale signalizované nepřístupné body.", "wrong": ["Nikdy", "Vždy, délka je jen kontrolní", "Při orientaci na tři body"], "note": "", "weak": false},
  {"id": "T3-076", "test": "T3", "set": "T3-tip", "topic": "Síť pomocných měřických bodů", "q": "Jaké minimální měření vyžaduje volné polární stanovisko?", "a": "2 směry + 2 délky na body polohových bodových polí nebo pomocné body (vždy raději víc).", "wrong": ["2 směry + 1 délka", "1 směr + 2 délky", "3 směry bez délek"], "note": "", "weak": false},
  {"id": "T3-077", "test": "T3", "set": "T3-tip", "topic": "Síť pomocných měřických bodů", "q": "Kolik podrobných bodů musí být minimálně jako dané body, slouží-li podrobné body jako dané pro stanovisko?", "a": "Nejméně 3 a jejich poloha musí být ověřena.", "wrong": ["2", "1", "5"], "note": "", "weak": false},
  {"id": "T3-078", "test": "T3", "set": "T3-tip", "topic": "Síť pomocných měřických bodů", "q": "Smí se z volného stanoviska určovat body protínáním vpřed?", "a": "Ne, z volného stanoviska nesmějí být určovány body protínáním vpřed.", "wrong": ["Ano, bez omezení", "Ano, jen ve 2 polohách", "Jen s GNSS"], "note": "", "weak": false},
  {"id": "T3-079", "test": "T3", "set": "T3-tip", "topic": "Podrobné body", "q": "Jak daleko od stanoviska smí ležet určovaný bod u polární metody?", "a": "Nejvýše 1,5× délka spojnice stanoviska s nejvzdálenějším orientačním bodem (přesáhne ji nejvýše o polovinu).", "wrong": ["Nejvýše 1000 m", "Nejvýše 2× nejbližší orientace", "Bez omezení"], "note": "", "weak": false},
  {"id": "T3-080", "test": "T3", "set": "T3-tip", "topic": "Podrobné body", "q": "Jak dlouhá smí být polární kolmice?", "a": "Nejvýše 1/2 délky od stanoviska k patě kolmice a nejvýše 30 m.", "wrong": ["3/4 délky a 30 m", "1/3 délky a 50 m", "Nejvýše 5 m"], "note": "", "weak": false},
  {"id": "T3-081", "test": "T3", "set": "T3-tip", "topic": "Podrobné body", "q": "Co je doměrek?", "a": "Změna délky na podrobný bod (+/−); znaménko − když má být měřená délka zkrácena.", "wrong": ["Výška cíle", "Délka kolmice", "Konstanta hranolu"], "note": "", "weak": false},
  {"id": "T3-082", "test": "T3", "set": "T3-tip", "topic": "Podrobné body", "q": "Kdy se použije metoda konstrukčních oměrných a jaká má omezení?", "a": "Pro pravoúhlé výstupky do 5 m u budov s pravoúhlými stěnami; dané body jsou vždy 2 (první a poslední), max. 8 určovaných bodů.", "wrong": ["Pro výstupky do 30 m, 10 bodů", "Pro kruhové objekty", "Pro body nad 50 m od stanoviska"], "note": "", "weak": false},
  {"id": "T3-083", "test": "T3", "set": "T3-tip", "topic": "Podrobné body", "q": "Jaké podmínky platí pro určení podrobných bodů ostatními metodami (mimo GNSS a polární)?", "a": "Připojení na jednoznačně identifikovatelné podrobné body (nebo síť) určené s nejméně stejnou přesností, vždy s nezávislou kontrolou (min. 3 body, kontrolní míry).", "wrong": ["Stačí připojení na 1 bod", "Bez kontroly", "Jen z mapy"], "note": "", "weak": false},
  {"id": "T3-084", "test": "T3", "set": "T3-tip", "topic": "Podrobné body", "q": "Jak se kontroluje poloha jednoznačně identifikovatelných podrobných bodů?", "a": "Kontrolními oměrnými mírami, křížovými mírami nebo dalším nezávislým měřením (i výšky).", "wrong": ["Odhadem z ortofota", "Jen výpočtem průměru", "Nekontroluje se"], "note": "", "weak": false},
  {"id": "T3-085", "test": "T3", "set": "T3-tip", "topic": "Podrobné body", "q": "Kdy se měří křížové míry?", "a": "Když oměrné míry nelze změřit (nebo jen velmi obtížně) nebo jsou delší než 50 m.", "wrong": ["Vždy místo oměrných", "Když jsou oměrné kratší než 5 m", "Jen u kružnic"], "note": "", "weak": false},
  {"id": "T3-086", "test": "T3", "set": "T3-tip", "topic": "Podrobné body", "q": "K čemu slouží kontrolní míry?", "a": "Ke kontrole vzájemné polohy podrobných bodů (ověření správnosti geometrického určení).", "wrong": ["K výpočtu výšek", "K orientaci stanoviska", "K určení konstanty hranolu"], "note": "", "weak": false},
  {"id": "T3-087", "test": "T3", "set": "T3-tip", "topic": "Podrobné body", "q": "Jak se zaměřuje kružnicový oblouk?", "a": "Třemi body – začátek, střed a konec měřeného oblouku.", "wrong": ["Dvěma body", "Středem a poloměrem", "Úsečkami po 0,7·uxy"], "note": "", "weak": false},
  {"id": "T3-088", "test": "T3", "set": "T3-tip", "topic": "Podrobné body", "q": "Jak se zaměřuje kružnice?", "a": "Třemi body rovnoměrně rozloženými na obvodu, nebo středem a poloměrem (vyznačí se v náčrtu).", "wrong": ["Dvěma body na průměru", "Jen středem", "Úsečkami"], "note": "", "weak": false},
  {"id": "T3-089", "test": "T3", "set": "T3-tip", "topic": "Podrobné body", "q": "Kdy se při měření rozlišují podrobné tvary předmětů polohopisu?", "a": "Když délka přímé spojnice lomových bodů dosahuje alespoň 0,7·uxy pro danou třídu přesnosti.", "wrong": ["Nad 0,5 m vždy", "Nad 1 m", "Nad uxy/4"], "note": "", "weak": false},
  {"id": "T3-090", "test": "T3", "set": "T3-tip", "topic": "Podrobné body", "q": "Jakou hodnotu má podle ČSN 01 3410 rozlišovací úroveň podrobných tvarů při číselném zpracování?", "a": "0,1 m (dříve vyjádřeno 0,7·uxy pro danou třídu přesnosti).", "wrong": ["0,5 m", "0,01 m", "1 m"], "note": "", "weak": false},
  {"id": "T3-091", "test": "T3", "set": "T3-tip", "topic": "Podrobné body", "q": "Co se dále zaměřuje/poznamenává u oplocení a opěrných zdí?", "a": "Šířky podezdívek nebo zděných sloupků u oplocení, šířky opěrných zdí apod.", "wrong": ["Výšky plotů", "Barvy plotů", "Nic"], "note": "", "weak": false},
  {"id": "T3-092", "test": "T3", "set": "T3-tip", "topic": "Výpočet souřadnic", "q": "Jaké jsou vstupní údaje pro výpočet souřadnic pomocných a podrobných bodů?", "a": "Seznam souřadnic užitých výchozích bodů, zápisníky nebo registrované výsledky podrobného měření a měřické náčrty.", "wrong": ["Jen ortofoto", "Jen seznam souřadnic", "Katastrální mapa"], "note": "", "weak": false},
  {"id": "T3-093", "test": "T3", "set": "T3-tip", "topic": "Výpočet souřadnic", "q": "Které naměřené údaje se při výpočtu souřadnic zpracují?", "a": "Všechny naměřené údaje včetně oměrných a jiných kontrolních měr.", "wrong": ["Jen polární měření", "Jen délky", "Jen body s kódem"], "note": "", "weak": false},
  {"id": "T3-094", "test": "T3", "set": "T3-tip", "topic": "Výpočet souřadnic", "q": "Co se dělá, jsou-li při výpočtu překročeny mezní odchylky?", "a": "Případy překročení se analyzují a chyby se opraví.", "wrong": ["Odchylky se ignorují", "Bod se smaže bez analýzy", "Mezní odchylky se zvětší"], "note": "", "weak": false},
  {"id": "T3-095", "test": "T3", "set": "T3-tip", "topic": "Výpočet souřadnic", "q": "Kdy lze použít obecný (vážený) aritmetický průměr?", "a": "Jen tehdy, jsou-li váhy dostatečně odborně zdůvodněny.", "wrong": ["Vždy", "Nikdy", "Jen u GNSS"], "note": "", "weak": false},
  {"id": "T3-096", "test": "T3", "set": "T3-tip", "topic": "Výpočet souřadnic", "q": "V jakých jednotkách a na kolik míst se udávají souřadnice?", "a": "V metrech, zaokrouhlené na dvě desetinná místa.", "wrong": ["V metrech na 3 místa", "V mm na celé číslo", "V metrech na 1 místo"], "note": "", "weak": false},
  {"id": "T3-097", "test": "T3", "set": "T3-tip", "topic": "Výpočet souřadnic", "q": "Co musí nejméně obsahovat protokol o výpočtu souřadnic?", "a": "Údaje o dosažených odchylkách v určovacích obrazcích měřické sítě (např. polygonových pořadech), při vícenásobném určení bodů a při porovnání oměrných a kontrolních měr se souřadnicemi.", "wrong": ["Jen seznam souřadnic", "Jen jméno zpracovatele", "Jen počet bodů"], "note": "", "weak": false},
  {"id": "T3-098", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Kolik je typových úloh a jak se číslují?", "a": "12 typových úloh, číslo 0 až 11.", "wrong": ["10 úloh, 1–10", "8 úloh, 0–7", "12 úloh, 1–12"], "note": "", "weak": false},
  {"id": "T3-099", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Vyjmenujte typové úlohy 0 až 5.", "a": "0 metoda pravoúhlých souřadnic, 1 polární metoda, 2 vyrovnání bodů do přímky, 3 průsečík dvou přímek, 4 konstrukční oměrné, 5 protínání z délek.", "wrong": ["0 polární, 1 pravoúhlé, 2 protínání zpět…", "0 konstrukční oměrné, 1 polární, 2 průsečík…", "0 protínání vpřed, 1 polární…"], "note": "", "weak": false},
  {"id": "T3-100", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Vyjmenujte typové úlohy 6 až 11.", "a": "6 redukce souřadnic o střešní přesah, 7 konstrukční oměrné s vyrovnáním na pravoúhlost, 8 protínání zpět, 9 kontrolní oměrné míry, 10 úprava obrazce na pravoúhlý, 11 metoda řídící přímky.", "wrong": ["6 protínání vpřed, 7 polární…", "6 kontrolní oměrné, 7 řídící přímka…", "6 průsečík přímek, 7 pravoúhlé…"], "note": "", "weak": false},
  {"id": "T3-101", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Jaké číslo má typová úloha polární metoda?", "a": "1.", "wrong": ["0", "8", "4"], "note": "", "weak": false},
  {"id": "T3-102", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Jaké číslo má metoda pravoúhlých souřadnic?", "a": "0.", "wrong": ["1", "2", "5"], "note": "", "weak": false},
  {"id": "T3-103", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Jaké číslo má metoda protínání zpět?", "a": "8.", "wrong": ["5", "3", "11"], "note": "", "weak": false},
  {"id": "T3-104", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Jaké číslo mají kontrolní oměrné míry?", "a": "9.", "wrong": ["4", "7", "10"], "note": "", "weak": false},
  {"id": "T3-105", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Jak se nazývají u typové úlohy 0 měřené délky ve směru měřické přímky?", "a": "Staničení.", "wrong": ["Kolmice", "Doměrek", "Oměrné"], "note": "", "weak": false},
  {"id": "T3-106", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Jaké znaménko má staničení u typové úlohy 0?", "a": "Od počátečního ke koncovému bodu „+“ (nevyznačuje se); na prodloužení před počáteční bod „−“.", "wrong": ["Vždy „−“", "„+“ jen za koncovým bodem", "Znaménko se nepoužívá"], "note": "", "weak": false},
  {"id": "T3-107", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Kdy má kolmice v typové úloze 0 záporné znaménko?", "a": "Leží-li zaměřovaný bod vlevo od měřické přímky v kladném směru staničení.", "wrong": ["Leží-li vpravo", "Je-li delší než 30 m", "Nikdy"], "note": "", "weak": false},
  {"id": "T3-108", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Kolik daných bodů má úloha 0 a které se zapisují jako první?", "a": "2–10 daných bodů, určovaných neomezeně; jako první dva se zapisují body nejvzdálenější.", "wrong": ["Vždy 2, první nejbližší", "4 dané body", "1 daný bod"], "note": "", "weak": false},
  {"id": "T3-109", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Co znamená symbolická nula u staničení druhého daného bodu v úloze 0?", "a": "Staničení nebylo měřeno (nedoměřená přímka); při dvou daných bodech je výpočet bez kontroly.", "wrong": ["Nulovou délku přímky", "Chybu měření", "Bod leží na počátku"], "note": "", "weak": false},
  {"id": "T3-110", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Kolik daných a orientačních bodů může mít polární metoda (úloha 1)?", "a": "Počet daných bodů včetně stanoviska 2–10, určovaných neomezeně; orientačních bodů u pevného stanoviska 2–9.", "wrong": ["Vždy 3 dané body", "1–5 daných bodů", "Neomezeně daných, max. 10 určovaných"], "note": "", "weak": false},
  {"id": "T3-111", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Jaké dva typy použití má polární metoda?", "a": "S pevným stanoviskem (známé souřadnice, výpočet orientačního posunu) a s volným stanoviskem (výpočet v pomocné soustavě a podobnostní transformace).", "wrong": ["S dálkoměrem a bez", "Jednopolohová a dvoupolohová", "Výšková a polohová"], "note": "", "weak": false},
  {"id": "T3-112", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Jak se u polární metody zapisuje pevné stanovisko a orientace?", "a": "Stanovisko jako první z daných bodů; jako první dva orientační body ty s nejkvalitnější orientací; délky na orientace mají jen kontrolní význam (neměřené = 0).", "wrong": ["Stanovisko jako poslední", "Orientace v libovolném pořadí", "Délky na orientace jsou povinné pro výpočet"], "note": "", "weak": false},
  {"id": "T3-113", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Jak se u polární metody zapisuje volné stanovisko?", "a": "Stanovisko se uvádí jako první z určovaných bodů a u všech daných bodů se měří vzdálenosti.", "wrong": ["Jako první z daných bodů", "Jako poslední bod", "Nezapisuje se"], "note": "", "weak": false},
  {"id": "T3-114", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Kdy má polární kolmice záporné znaménko?", "a": "Leží-li zaměřovaný bod vlevo od kladného směru polárního paprsku.", "wrong": ["Vpravo od paprsku", "Je-li delší než 30 m", "Nikdy"], "note": "", "weak": false},
  {"id": "T3-115", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Kdy se v zápisníku uvádí typ vzdálenosti?", "a": "Jen když se liší od typu na obálce zápisníku nebo u stanoviska; u stanoviska platí pro celou úlohu, u řádku jen pro ten řádek.", "wrong": ["U každého bodu vždy", "Nikdy", "Jen u GNSS"], "note": "", "weak": false},
  {"id": "T3-116", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Co řeší úloha 2 – vyrovnání bodů do přímky?", "a": "Výpočet souřadnic bodů jako pat kolmic spuštěných z daných bodů na přímku AB (nebo na její rovnoběžku danou bodem R).", "wrong": ["Průsečík dvou přímek", "Úpravu obrazce na pravoúhlý", "Redukci o střešní přesah"], "note": "", "weak": false},
  {"id": "T3-117", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Kolik daných a určovaných bodů má úloha 3 – průsečík dvou přímek?", "a": "Vždy 4 dané body (dvojice 1. a 2. přímky) a 1 určovaný bod.", "wrong": ["2 dané a 2 určované", "3 dané a 1 určovaný", "4 dané a 4 určované"], "note": "", "weak": false},
  {"id": "T3-118", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Jak se zapisují oměrné míry v úloze 4 a jaká je první oměrná?", "a": "Se znaménkem „−“, leží-li koncový bod vlevo od spojnice předchozích dvou bodů ve směru postupu, vpravo kladně; první oměrná je vždy kladná.", "wrong": ["První oměrná je vždy záporná", "Bez znamének", "Znaménko podle délky"], "note": "", "weak": false},
  {"id": "T3-119", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Jak funguje úloha 5 – protínání z délek?", "a": "Souřadnice bodu z vzdáleností od dvou daných bodů (lze odvodit z ortogonálních údajů); ve sloupci kolmic +1, leží-li bod vpravo od směru z 1. na 2. bod, −1 vlevo.", "wrong": ["Ze tří směrů", "Ze staničení a kolmice", "Z výšek bodů"], "note": "", "weak": false},
  {"id": "T3-120", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Jak se zapisuje úloha 6 – redukce o střešní přesah?", "a": "V uzavřených půdorysech (nebo jejich částech) ve směru hodinových ručiček; u části půdorysu se krajní body neredukují; max. 50 bodů.", "wrong": ["Proti směru hodinových ručiček", "Jen u kruhových budov", "Max. 8 bodů"], "note": "", "weak": false},
  {"id": "T3-121", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Co je potřeba pro úlohu 7 – konstrukční oměrné s vyrovnáním na pravoúhlost?", "a": "Musí být známy všechny oměrné, přesahy měřeny aspoň pro redukci daných bodů (neměřené = 0); zápis v uzavřených půdorysech ve směru hodinových ručiček.", "wrong": ["Stačí jedna oměrná", "Žádné oměrné", "Jen souřadnice všech bodů"], "note": "", "weak": false},
  {"id": "T3-122", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Jak se zapisuje úloha 8 – protínání zpět?", "a": "Osnova směrů na 3 nebo 4 dané body (výpočet v 1 nebo 2 kombinacích); jako první dva body s nejkvalitnějšími směry.", "wrong": ["Na 2 dané body", "Délky na 3 body", "Na 5 a více bodů"], "note": "", "weak": false},
  {"id": "T3-123", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Jak se zapisuje protínání vpřed?", "a": "Netvoří samostatnou úlohu – zapisuje se v úlohách polární metody s pevným stanoviskem s nulovou délkou i doměrkem, poznámka „protínání vpřed“, bod alespoň ve dvou úlohách.", "wrong": ["Jako úloha 8", "Jako úloha 5", "Nelze ho zapsat"], "note": "", "weak": false},
  {"id": "T3-124", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Jaké kombinace se vynechají u protínání vpřed z více stanovisek?", "a": "Nepříznivé kombinace s úhlem protnutí menším než nastavená mez (v toleranci Mapování 1 je min. úhel protnutí 30 gon).", "wrong": ["Všechny kromě první", "Žádné", "Kombinace s délkou nad 100 m"], "note": "", "weak": false},
  {"id": "T3-125", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Ve kterých dvou formách lze zapsat kontrolní oměrné míry (úloha 9)?", "a": "Řetěz navazujících oměrných (společný bod se neopakuje) nebo vzájemně nezávislé oměrné / křížové míry (dvojice koncových bodů).", "wrong": ["Jen jako řetěz", "Jen ve stanovisku", "Jako polární měření"], "note": "", "weak": false},
  {"id": "T3-126", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Jaké podmínky platí pro úlohu 10 – úpravu obrazce na pravoúhlý?", "a": "Na každé straně aspoň 1 daný bod, aspoň na jedné straně 2; nejdelší strana max. 4/3 nejdelší spojnice daných bodů; obrazec max. 20 lomových bodů.", "wrong": ["Stačí 2 body celkem", "Max. 50 lomových bodů", "Nejdelší strana max. 1/3 spojnice"], "note": "", "weak": false},
  {"id": "T3-127", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Co je metoda řídící přímky (úloha 11)?", "a": "Úprava obrazce na pravoúhlý se zachováním směrníku zadané spojnice dvou daných bodů – všechny strany jsou s ní rovnoběžné nebo na ni kolmé.", "wrong": ["Protínání zpět ze 3 bodů", "Vyrovnání bodů do přímky", "Redukce o střešní přesah"], "note": "", "weak": false},
  {"id": "T3-128", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy", "q": "Které typové úlohy jsou čistě početní?", "a": "2 vyrovnání bodů do přímky, 3 průsečík přímek, 10 úprava obrazce na pravoúhlý, 11 řídící přímka (na slajdu vyznačeny modře).", "wrong": ["0 a 1", "5 a 8", "4 a 9"], "note": "", "weak": false},
  {"id": "T3-129", "test": "T3", "set": "T3-tip", "topic": "Zápisník podrobného měření", "q": "Jakou podobu mohou mít zápisníky podrobného měření a z čeho se skládá analogový?", "a": "Analogovou či digitální; analogový má obálku a vlastní zápisník.", "wrong": ["Jen digitální", "Jen analogovou bez obálky", "Tištěnou mapu"], "note": "", "weak": false},
  {"id": "T3-130", "test": "T3", "set": "T3-tip", "topic": "Zápisník podrobného měření", "q": "Jaké číslo má zápisník podrobného měření?", "a": "Shodné s číslem měřického náčrtu (více zápisníků k jednomu náčrtu se rozliší podlomením).", "wrong": ["Číslo k.ú.", "Pořadové číslo stanoviska", "Číslo přístroje"], "note": "", "weak": false},
  {"id": "T3-131", "test": "T3", "set": "T3-tip", "topic": "Zápisník podrobného měření", "q": "Jak se pojmenuje soubor registrovaných naměřených hodnot?", "a": "Obsahuje číslo zápisníku, místo lomítka se použije podtržítko.", "wrong": ["Datem měření", "Jménem měřiče", "Číslem přístroje"], "note": "", "weak": false},
  {"id": "T3-132", "test": "T3", "set": "T3-tip", "topic": "Zápisník podrobného měření", "q": "Co se zapisuje v řádku stanoviska polární metody?", "a": "Číslo bodu a výška přístroje.", "wrong": ["Teplota a tlak", "Konstanta hranolu", "Číslo zápisníku"], "note": "", "weak": false},
  {"id": "T3-133", "test": "T3", "set": "T3-tip", "topic": "Zápisník podrobného měření", "q": "Co se udělá, když se výšky u bodů nebo stanoviska neměří?", "a": "Záznam do příslušných sloupců zápisníku se vynechá.", "wrong": ["Zapíše se 0", "Zapíše se výška z mapy", "Zapíše se −1"], "note": "", "weak": false},
  {"id": "T3-134", "test": "T3", "set": "T3-tip", "topic": "Zápisník podrobného měření", "q": "Jaké údaje jsou na obálce zápisníku (organizační údaje)?", "a": "Lokalita, k.ú. a jeho číslo, číslo pracoviště, číslo náčrtu (ZPMZ), pořadové číslo zápisníku, kód kvality, souřadnicový systém, přístroj, typ vzdálenosti, kdo měřil a zapsal, datum.", "wrong": ["Jen jméno měřiče", "Jen souřadnice bodů", "Jen datum"], "note": "", "weak": false},
  {"id": "T3-135", "test": "T3", "set": "T3-tip", "topic": "Export, import a Trimble Access (přednáška 5)", "q": "Jaké souřadnice používá S-JTSK EPSG:5514?", "a": "Záporné souřadnice Y (Sever), X (Východ) – orientace SV.", "wrong": ["Kladné X (Jih), Y (Západ)", "Zeměpisné souřadnice WGS84", "Kladné Y (Sever), X (Východ)"], "note": "", "weak": false},
  {"id": "T3-136", "test": "T3", "set": "T3-tip", "topic": "Export, import a Trimble Access (přednáška 5)", "q": "Jaké souřadnice používá S-JTSK EPSG:5513?", "a": "Kladné souřadnice X (Jih), Y (Západ).", "wrong": ["Záporné Y (Sever), X (Východ)", "Geocentrické X, Y, Z", "UTM"], "note": "", "weak": false},
  {"id": "T3-137", "test": "T3", "set": "T3-tip", "topic": "Export, import a Trimble Access (přednáška 5)", "q": "Kde se podle přednášky provádí export do EPSG:5514 a 5513?", "a": "Export v PC.", "wrong": ["Jen v přístroji", "Jen v GNSS kontroleru", "Vůbec se neexportuje"], "note": "", "weak": false},
  {"id": "T3-138", "test": "T3", "set": "T3-tip", "topic": "Export, import a Trimble Access (přednáška 5)", "q": "Jakou novou možnost Trimble Access (od 2021) uvádí přednáška pro vícenásobné určení bodů?", "a": "Připravenost TA na vícenásobné určení a průměrování bodů pod stejným číslem – optimální, výsledky jsou vidět hned (ve starším TA nefunguje).", "wrong": ["Automatickou transformaci do WGS84", "Měření bez hranolu", "Automatické kódování"], "note": "", "weak": false},
  {"id": "T3-139", "test": "T3", "set": "T3-tip", "topic": "Export, import a Trimble Access (přednáška 5)", "q": "Jak funguje číslování pro automatické průměrování s tečkou PŘED číslem bodu?", "a": "Před číslo bodu se dá pořadové číslo zaměření a tečka (např. 1.4001 a 2.4001); při exportu se protokolárně zprůměrují; nevýhoda: v TA jsou to různé body a nevidíme hned rozdíly.", "wrong": ["4001.1 a 4001.2 – nejlepší varianta", "Body se průměrují už v TA", "Takové číslování nejde"], "note": "", "weak": false},
  {"id": "T3-140", "test": "T3", "set": "T3-tip", "topic": "Export, import a Trimble Access (přednáška 5)", "q": "Jak funguje číslování pro automatické průměrování s tečkou ZA číslem bodu a jak je hodnoceno?", "a": "Za číslo bodu se dá tečka a pořadové číslo zaměření (4001.1, 4001.2); při exportu se zprůměrují; oproti předchozím variantám má více nevýhod.", "wrong": ["Je to nejlepší varianta", "Body se nikdy nezprůměrují", "Funguje jen u GNSS"], "note": "", "weak": false},
  {"id": "T3-141", "test": "T3", "set": "T3-tip", "topic": "Export, import a Trimble Access (přednáška 5)", "q": "Jaký protokol se exportuje pro katastr nemovitostí?", "a": "„CZ Katastr – protokol měření“; protokol bez výšek (pro KN).", "wrong": ["Protokol s výškami povinně", "DXF výkres", "Seznam WGS84 souřadnic"], "note": "", "weak": false},
  {"id": "T3-142", "test": "T3", "set": "T3-tip", "topic": "Export, import a Trimble Access (přednáška 5)", "q": "Co jsou registrovaná data u totální stanice?", "a": "SD (šikmá délka), Z (zenitový úhel), HP (vodorovný směr – pozor na HL!) a výšky cíle; u stanoviska výška stroje.", "wrong": ["Jen souřadnice Y, X, Z", "Jen vodorovné délky", "Teplota a tlak"], "note": "", "weak": false},
  {"id": "T3-143", "test": "T3", "set": "T3-tip", "topic": "Export, import a Trimble Access (přednáška 5)", "q": "Jak lze u měření na dané body zajistit správný export do formátu Mapa2?", "a": "Kódem (např. OR) u orientací – jinak orientace nejsou definovány a je třeba zápisník zeditovat.", "wrong": ["Kódem PB u podrobných bodů", "Nelze, vždy se edituje ručně", "Zapnutím GNSS"], "note": "", "weak": false},
  {"id": "T3-144", "test": "T3", "set": "T3-tip", "topic": "Export, import a Trimble Access (přednáška 5)", "q": "Jaké tři skupiny korekcí měřených délek uvádí přednáška?", "a": "Matematické, fyzikální a konstanta hranolu.", "wrong": ["Statické, dynamické, kinematické", "Polohové, výškové, časové", "Hrubé, systematické, nahodilé"], "note": "", "weak": false},
  {"id": "T3-145", "test": "T3", "set": "T3-tip", "topic": "Export, import a Trimble Access (přednáška 5)", "q": "Co je parametrem určujícím měřítko elektronicky měřených délek?", "a": "Vlnová délka, případně rychlost šíření elektromagnetického záření v prostředí.", "wrong": ["Konstanta hranolu", "Nadmořská výška", "Měřítkový faktor zobrazení"], "note": "", "weak": false},
  {"id": "T3-146", "test": "T3", "set": "T3-tip", "topic": "Export, import a Trimble Access (přednáška 5)", "q": "Jak se postihují změny vlnové délky a rychlosti šíření záření?", "a": "Měřením teploty a tlaku (případně vlhkosti) vzduchu – fyzikální korekce.", "wrong": ["Redukcí na nulový horizont", "Konstantou hranolu", "Měřením výšky cíle"], "note": "", "weak": false},
  {"id": "T3-147", "test": "T3", "set": "T3-tip", "topic": "Export, import a Trimble Access (přednáška 5)", "q": "Kdo zavádí fyzikální korekci a podle čeho?", "a": "Výrobce udává v manuálu vzorce; přístroj po zadání teploty a tlaku zavede opravu sám (případně si je sám změří). Lze spočítat i ze vzorců (Barrell–Sears).", "wrong": ["Jen ručně v kanceláři", "Zavádí ji katastrální úřad", "Nezavádí se nikdy"], "note": "", "weak": false},
  {"id": "T3-148", "test": "T3", "set": "T3-tip", "topic": "Export, import a Trimble Access (přednáška 5)", "q": "Jaký je následek opomenutí nebo špatného zavedení fyzikálních korekcí?", "a": "Systematická chyba v měřítku délek.", "wrong": ["Hrubá chyba v úhlu", "Nahodilá chyba ve výšce", "Žádný"], "note": "", "weak": false},
  {"id": "T3-149", "test": "T3", "set": "T3-tip", "topic": "Export, import a Trimble Access (přednáška 5)", "q": "Kdy se zavádějí matematické korekce délek?", "a": "V S-JTSK (mapa, konformní kartografické zobrazení) se zavádějí; v místním systému (plán) se nezavádějí.", "wrong": ["Vždy, i v místním systému", "Nikdy", "Jen u nivelace"], "note": "", "weak": false},
  {"id": "T3-150", "test": "T3", "set": "T3-tip", "topic": "Export, import a Trimble Access (přednáška 5)", "q": "Kde všude lze zavést matematické korekce (a na co pozor)?", "a": "Přímo v softwaru totální stanice, při exportu měřených dat nebo před výpočtem (při importu zápisníku do výpočetního SW) – pozor na kombinace (zavést jen jednou).", "wrong": ["Jen v přístroji", "Jen v katastru", "Jen ručně do náčrtu"], "note": "", "weak": false},
  {"id": "T3-151", "test": "T3", "set": "T3-tip", "topic": "Export, import a Trimble Access (přednáška 5)", "q": "Jaká nastavení jobu v Trimble Access přednáška ukazuje?", "a": "Souřadnicový systém, jednotky, aktivní mapy a kódování, CoGo.", "wrong": ["Jen jas displeje", "Jen jazyk", "Jen heslo"], "note": "", "weak": false},
  {"id": "T3-152", "test": "T3", "set": "T3-tip", "topic": "Export, import a Trimble Access (přednáška 5)", "q": "Jak GROMA zavádí zvolené opravy délek?", "a": "Vypočtený měřítkový koeficient uloží do nastavení a při importu seznamu měření všechny importované délky tímto koeficientem vynásobí.", "wrong": ["Přičte konstantu ke každé délce", "Opraví jen úhly", "Opraví až souřadnice"], "note": "", "weak": false},
  {"id": "T3-153", "test": "T3", "set": "T3-tip", "topic": "Export, import a Trimble Access (přednáška 5)", "q": "Jakým číslem se násobí délky, když matematické korekce zavádíme už v přístroji (a při importu do GROMY)?", "a": "Při importu do GROMY se pak délky násobí 1 (korekce se nezavádí podruhé).", "wrong": ["Měřítkem 0,9999", "Dvojkou", "Konstantou hranolu"], "note": "", "weak": false},
  {"id": "T3-154", "test": "T3", "set": "T3-tip", "topic": "Export, import a Trimble Access (přednáška 5)", "q": "Jaké údaje obsahuje hlavička zápisníku měření při importu (přednáška 5)?", "a": "Zavedená korekce, pracoviště, číslo KÚ, číslo náčrtu, zpracování, třída přesnosti, soustava a typ délek.", "wrong": ["Jen číslo bodu", "Jen jméno měřiče", "Teplota a tlak"], "note": "", "weak": false},
  {"id": "T3-155", "test": "T3", "set": "T3-tip", "topic": "Zpracování dat (přednáška 6)", "q": "Jakými metodami se určují souřadnice pomocných měřických bodů?", "a": "Rajony, pomocné polygonové pořady, protínání ze směrů (popř. z délek), volné polární stanovisko, plošné sítě (vyrovnání sítě).", "wrong": ["Jen GNSS", "Jen ortogonálně", "Konstrukčními oměrnými"], "note": "", "weak": false},
  {"id": "T3-156", "test": "T3", "set": "T3-tip", "topic": "Zpracování dat (přednáška 6)", "q": "Jakými metodami se určují výšky pomocných bodů?", "a": "Technickou nivelací, trigonometricky (výškový pořad) a výškovými sítěmi (vyrovnání sítě).", "wrong": ["Jen z vrstevnic", "Barometricky", "Jen GNSS"], "note": "", "weak": false},
  {"id": "T3-157", "test": "T3", "set": "T3-tip", "topic": "Zpracování dat (přednáška 6)", "q": "Jakými metodami se určují podrobné body?", "a": "Polární metodou, tachymetrií (prostorová polární metoda) a plošnou nivelací.", "wrong": ["Jen protínáním zpět", "Jen GNSS statikou", "Jen pásmem"], "note": "", "weak": false},
  {"id": "T3-158", "test": "T3", "set": "T3-tip", "topic": "Zpracování dat (přednáška 6)", "q": "Co je nutné udělat jako první před zpracováním dat v software?", "a": "Software vždy nejdřív nastavit.", "wrong": ["Smazat staré body", "Vytisknout náčrt", "Nic"], "note": "", "weak": false},
  {"id": "T3-159", "test": "T3", "set": "T3-tip", "topic": "Zpracování dat (přednáška 6)", "q": "Jak se v GROMĚ zpracovávají polární měření?", "a": "Polární metodou dávkou (+ rajony a volná polární stanoviska) a polygonové pořady; pozor na vícenásobné určení souřadnic.", "wrong": ["Jen ručně bod po bodu", "Jen v GNSS modulu", "Nezpracovávají se"], "note": "", "weak": false},
  {"id": "T3-160", "test": "T3", "set": "T3-tip", "topic": "Zpracování dat (přednáška 6)", "q": "Co ukazuje protokol „Opravy orientací“ v GROMĚ?", "a": "Pro každou orientaci vodorovný směr, váhu, směrník, opravu orientace, délky a opravy; upozorní na překročení mezní opravy (např. 0,0254 g při mezi 0,0200 g – „zamyslet se“).", "wrong": ["Jen souřadnice stanoviska", "Jen výšky", "Seznam kódů"], "note": "", "weak": false},
  {"id": "T3-161", "test": "T3", "set": "T3-tip", "topic": "Zpracování dat (přednáška 6)", "q": "Co obsahuje protokol kontrolního (dvojího) určení bodu v GROMĚ?", "a": "Staré a nové souřadnice, rozdíl, polohovou odchylku a střední souřadnicovou chybu; uložený výsledek (průměr nebo nová hodnota).", "wrong": ["Jen nové souřadnice", "Jen číslo bodu", "Jen výšku"], "note": "", "weak": false},
  {"id": "T3-162", "test": "T3", "set": "T3-tip", "topic": "Zpracování dat (přednáška 6)", "q": "Jak se obvykle provádí polohové a výškové vyrovnání sítě?", "a": "Většinou odděleně.", "wrong": ["Vždy společně", "Jen výškové", "Jen polohové"], "note": "", "weak": false},
  {"id": "T3-163", "test": "T3", "set": "T3-tip", "topic": "Zpracování dat (přednáška 6)", "q": "Jaký je rozdíl mezi volnou a vázanou sítí?", "a": "Volná síť není vázána na pevné body (definována vnitřně), vázaná síť je připojena na pevné (dané) body; body jsou pevné nebo volné.", "wrong": ["Volná má víc bodů", "Vázaná nemá dané body", "Není rozdíl"], "note": "", "weak": false},
  {"id": "T3-164", "test": "T3", "set": "T3-tip", "topic": "Zpracování dat (přednáška 6)", "q": "Čím se řídí společné vyrovnání délek a směrů?", "a": "Poměrem apriorních přesností (střední chyba směru a střední chyba délky).", "wrong": ["Počtem bodů", "Konstantou hranolu", "Teplotou"], "note": "", "weak": false},
  {"id": "T3-165", "test": "T3", "set": "T3-tip", "topic": "Zpracování dat (přednáška 6)", "q": "Jaký je postup výpočtu sítě (8 kroků)?", "a": "1) kontrola parametrů projektu, 2) import a kontrola zápisníků, 3) import daných bodů, 4) přibližný výpočet, 5) polohové vyrovnání, 6) výškové vyrovnání, 7) odstranění hrubých chyb a opakování, 8) export bodů.", "wrong": ["Vyrovnání, import, export", "Export, import, kontrola", "Jen přibližný výpočet"], "note": "", "weak": false},
  {"id": "T3-166", "test": "T3", "set": "T3-tip", "topic": "Zpracování dat (přednáška 6)", "q": "Lze parametry (apriorní přesnosti) sítě univerzálně stanovit?", "a": "Ne – závisí na přístrojích, technologii měření a konfiguraci sítě; liší se od teoretických (výrobce); lze je nastavit pro každou veličinu.", "wrong": ["Ano, vždy podle výrobce", "Ano, 1 mm a 1 cc", "Nastavují se náhodně"], "note": "", "weak": false},
  {"id": "T3-167", "test": "T3", "set": "T3-tip", "topic": "Zpracování dat (přednáška 6)", "q": "Co se udělá, když po vyrovnání nesedí poměr m0 aposteriorní / m0 apriorní?", "a": "Upraví se apriorní přesnosti – musí však být akceptovatelné a reálné.", "wrong": ["Smaže se síť", "Změní se souřadnice daných bodů", "Nic se nedělá"], "note": "", "weak": false},
  {"id": "T3-168", "test": "T3", "set": "T3-tip", "topic": "Zpracování dat (přednáška 6)", "q": "Co se sleduje v protokolu z vyrovnání sítě?", "a": "Poměr m0 aposteriorní / m0 apriorní, podezřelá měření, opravy vybočující z testu, dosažená a požadovaná přesnost, elipsy chyb.", "wrong": ["Jen seznam bodů", "Jen počasí", "Jen počet stanovisek"], "note": "", "weak": false},
  {"id": "T3-169", "test": "T3", "set": "T3-tip", "topic": "Zpracování dat (přednáška 6)", "q": "Ve kterých programech se v přednášce zpracovávají data?", "a": "GROMA (polární metoda, protokoly), GEUS (nivelace, síť) a Gnet mini – VKM (vyrovnání sítě).", "wrong": ["AutoCAD a Excel", "QGIS a ArcGIS", "Jen Trimble Business Center"], "note": "", "weak": false},
  {"id": "T3-170", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Signály kterých družic lze podle přílohy 9 pro měření využít?", "a": "Signály všech zprovozněných a správně fungujících družic všech dostupných globálních navigačních družicových systémů založených na obdobném principu jako GPS-NAVSTAR.", "wrong": ["Jen GPS-NAVSTAR", "Jen GPS a GLONASS", "Jen Galileo"], "note": "", "weak": false},
  {"id": "T3-171", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Jak dlouhá musí být doba měření na bodě u statických metod?", "a": "Dostatečně dlouhá vzhledem k metodě měření, délce vektoru, použitým aparaturám a počtu družic ve výsledku zpracování.", "wrong": ["Vždy 5 minut", "Vždy 24 hodin", "Nejméně 5 záznamů"], "note": "", "weak": false},
  {"id": "T3-172", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Jak dlouhá smí být vzdálenost bodů, mezi nimiž se vztahy GNSS přímo určují?", "a": "Ne delší, než je maximální vzdálenost řešitelná použitým zpracovatelským programem.", "wrong": ["Nejvýše 1000 m", "Nejvýše 10 km vždy", "Bez omezení"], "note": "", "weak": false},
  {"id": "T3-173", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Jaké přesnosti musí vyhovět souřadnice bodu určeného GNSS?", "a": "Charakteristikám přesnosti pro trigonometrické a zhušťovací body (vyhláška) a pro body PPBP a podrobné body (zvláštní předpis).", "wrong": ["Jen přesnosti 5. třídy", "Jen PDOP pod 7", "Žádné"], "note": "", "weak": false},
  {"id": "T3-174", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Jak lze ověřit pomocný bod určený klasicky z neověřených GNSS bodů?", "a": "Kontrolním určením souřadnic nejméně dvou nezávisle určených bodů z tohoto bodu, nebo jeho kontrolním zaměřením z jiných (nezávisle určených) GNSS bodů.", "wrong": ["Nelze ho ověřit", "Stačí změřit jeho výšku", "Odečtem z ortofota"], "note": "", "weak": false},
  {"id": "T3-175", "test": "T3", "set": "T3-tip", "topic": "GNSS – vyhláška 31/1995 Sb., příloha 9", "q": "Kdo schvaluje program pro transformaci z WGS84/ETRS89 do S-JTSK?", "a": "Úřad (Český úřad zeměměřický a katastrální).", "wrong": ["Výrobce přijímače", "Katastrální úřad v místě", "Nikdo"], "note": "", "weak": false},
  {"id": "T3-176", "test": "T3", "set": "T3-tip", "topic": "Přesnost a síť – doplňky", "q": "Na čem podle přednášky reálně závisí mezní odchylka v orientaci?", "a": "Na délkách orientací (pro předmět je stanovena pevně 0,04 gon).", "wrong": ["Na teplotě", "Na počtu podrobných bodů", "Na typu hranolu"], "note": "", "weak": false},
  {"id": "T3-177", "test": "T3", "set": "T3-tip", "topic": "Přesnost a síť – doplňky", "q": "Jak se ověří orientace polární metody, nelze-li zaměřit více než jeden orientační směr?", "a": "Na jednoznačně identifikovatelném podrobném bodu určeném ve stejné třídě přesnosti (kontrolně zaměřeném z jiného stanoviska).", "wrong": ["Nijak", "Měřením na sever", "Opakováním na stejný bod"], "note": "", "weak": false},
  {"id": "T3-178", "test": "T3", "set": "T3-tip", "topic": "Přesnost a síť – doplňky", "q": "Jaké elektronické dálkoměry se využívají při zaměřování bodů měřické sítě?", "a": "Zpravidla elektronické dálkoměry s optickými odraznými systémy.", "wrong": ["Ruční laserové dálkoměry", "Pásmo", "Ultrazvukové dálkoměry"], "note": "", "weak": false},
  {"id": "T3-179", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy – doplňky", "q": "Jak se v zápisníku polární metody oddělují dané a určované body?", "a": "Podtržením.", "wrong": ["Prázdným řádkem", "Hvězdičkou", "Kódem OR"], "note": "", "weak": false},
  {"id": "T3-180", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy – doplňky", "q": "Kolik daných podrobných bodů je třeba, slouží-li podrobné body jako dané body úlohy (pozor u úlohy 0)?", "a": "Nejméně 3 (a jejich poloha musí být ověřena).", "wrong": ["2", "1", "4"], "note": "", "weak": false},
  {"id": "T3-181", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy – doplňky", "q": "Co představují grafická znázornění u jednotlivých typových úloh?", "a": "Zároveň vzor zákresu příslušné metody a zápisu měřených údajů do náčrtu (vyjma barevnosti).", "wrong": ["Jen ilustraci bez významu", "Vzor protokolu", "Vzor mapové značky"], "note": "", "weak": false},
  {"id": "T3-182", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy – doplňky", "q": "Jak se zapisují dané body u úlohy 3 (průsečík přímek)?", "a": "Předepisují se jen čísla bodů v pořadí dvojice bodů 1. přímky, dvojice bodů 2. přímky; dané body se oddělí podtržením.", "wrong": ["S měřenými délkami", "V libovolném pořadí", "Jen 2 body"], "note": "", "weak": false},
  {"id": "T3-183", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy – doplňky", "q": "Co se u úlohy 5 uvádí mezi danými body?", "a": "Kontrolně měřená vzdálenost mezi danými body, nebo nula, nebyla-li měřena.", "wrong": ["Směrník", "Výška", "Nic"], "note": "", "weak": false},
  {"id": "T3-184", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy – doplňky", "q": "Jak vypadá forma záznamu úlohy 6 (střešní přesah)?", "a": "Číslo bodu, přesah 1 ve sloupci staničení, oměrná ve sloupci kolmice, přesah 2 ve sloupci svislý úhel.", "wrong": ["Jen čísla bodů", "Délka a směr", "Přesah ve sloupci poznámka"], "note": "", "weak": false},
  {"id": "T3-185", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy – doplňky", "q": "Co se stane v úloze 6, když porovnání oměrné měřené a vypočtené překročí mezní odchylku?", "a": "Vyrovnání ani výpočet vložených měr se neprovede; hledá se další možná poloha rohového bodu protínáním z délek a volí se podle velikosti vzniklého vrcholového úhlu.", "wrong": ["Bod se smaže", "Odchylka se rozdělí", "Výpočet proběhne normálně"], "note": "", "weak": false},
  {"id": "T3-186", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy – doplňky", "q": "Pro jaké objekty je použitelná úloha 7?", "a": "Pro objekty pravoúhlého půdorysu – při fotogrammetrickém vyhodnocení i při mapování geodetickými metodami.", "wrong": ["Jen pro kruhové objekty", "Jen pro GNSS body", "Jen pro silnice"], "note": "", "weak": false},
  {"id": "T3-187", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy – doplňky", "q": "Jaké znaménko mají oměrné v úloze 7 u jednoduchého čtyřúhelníku?", "a": "Všechny jsou kladné (znaménko + se nemusí uvádět).", "wrong": ["Všechny záporné", "Střídavě", "První záporná"], "note": "", "weak": false},
  {"id": "T3-188", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy – doplňky", "q": "Kolik kontrolních délek lze zapsat v úloze 9?", "a": "Prakticky neomezené množství (skupinová úloha).", "wrong": ["Nejvýše 8", "Nejvýše 50", "Jen jednu"], "note": "", "weak": false},
  {"id": "T3-189", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy – doplňky", "q": "Jak se u úlohy 10 zapisuje uzavřený a neuzavřený obrazec?", "a": "Uzavřený: číslo počátečního lomového bodu se na konci opakuje. Neuzavřený: musí být dány první a poslední lomový bod, ty se nemění.", "wrong": ["Oba stejně", "Neuzavřený nelze upravit", "Uzavřený bez opakování bodu"], "note": "", "weak": false},
  {"id": "T3-190", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy – doplňky", "q": "Kolik doplňujících bodů smí být na jedné straně obrazce v úloze 10?", "a": "Kromě lomových bodů nejvýše dva doplňující body.", "wrong": ["Neomezeně", "Žádný", "Nejvýše pět"], "note": "", "weak": false},
  {"id": "T3-191", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy – doplňky", "q": "Co se zapisuje v záhlaví úlohy 11 (řídící přímka)?", "a": "Kromě typu úlohy čísla bodů s danými souřadnicemi definujících řídící přímku; spojnice prvních dvou lomových bodů musí být s ní rovnoběžná.", "wrong": ["Jen číslo úlohy", "Směrník v gonech", "Délky stran"], "note": "", "weak": false},
  {"id": "T3-192", "test": "T3", "set": "T3-tip", "topic": "Typové úlohy – doplňky", "q": "Jaký je kód kvality podrobných bodů uvedený v ukázce obálky zápisníku?", "a": "3.", "wrong": ["1", "5", "8"], "note": "", "weak": false},
  {"id": "T3-193", "test": "T3", "set": "T3-tip", "topic": "Nivelace a zpracování", "q": "Jaké typy záměr se objevují v zápisníku plošné nivelace v GEUS?", "a": "B – záměra vzad, F – záměra vpřed, I – mezilehlé (boční) záměry na podrobné body.", "wrong": ["Jen F", "S a O", "A a Z"], "note": "", "weak": false},
  {"id": "T3-194", "test": "T3", "set": "T3-tip", "topic": "Nivelace a zpracování", "q": "Co je třeba udělat, než začneme v programu počítat s ukázkovými daty z přednášky (upozornění na číslování)?", "a": "Uvědomit si, že v příkladech přednášky není použito korektní číslování bodů – v praxi číslovat správně podle pravidel.", "wrong": ["Nic", "Smazat výšky", "Přepočítat do WGS84"], "note": "", "weak": false},
  {"id": "T3-195", "test": "T3", "set": "T3-tip", "topic": "Výpůjčky přístrojů (přednáška 5)", "q": "Jak a s jakým předstihem se vytváří výpůjčka přístrojů ze skladu GED?", "a": "V systému výpůjček GED (intranet FAST) jako „Nová výpůjčka“, s předstihem 1 den předem; bez ní se vybavení nevydá.", "wrong": ["Telefonicky v den měření", "E-mailem týden předem", "Bez objednávky"], "note": "", "weak": false},
  {"id": "T3-196", "test": "T3", "set": "T3-tip", "topic": "Výpůjčky přístrojů (přednáška 5)", "q": "Co je nutné nastavit ve výpůjčce?", "a": "Účel (rozvrhovou jednotku předmětu), termín vyzvednutí, termín vrácení a přechodné umístění majetku.", "wrong": ["Jen jméno", "Jen typ přístroje", "Číslo účtu"], "note": "", "weak": false},
  {"id": "T3-197", "test": "T3", "set": "T3-tip", "topic": "Výpůjčky přístrojů (přednáška 5)", "q": "Kdy se přístroje vyzvedávají a vracejí a jaká je standardní doba výpůjčky?", "a": "Vyzvednutí po–čt (pá po dohodě) cca 8–15 h, vrácení po–čt v 8 h; standardní doba 24 hodin, popř. na víkend.", "wrong": ["Kdykoli, 1 týden", "Jen v pátek, 3 dny", "Po–pá 6–20 h, 48 h"], "note": "", "weak": false},
  {"id": "T3-198", "test": "T3", "set": "T3-tip", "topic": "Výpůjčky přístrojů (přednáška 5)", "q": "Co platí o termínech vyzvednutí a vrácení přístrojů?", "a": "Je nutné dodržet termín z objednávky; jindy nemusí být vybavení vydáno; v jakém stavu se převezme, v takovém se vrací.", "wrong": ["Termíny jsou orientační", "Vrátit lze kdykoli", "Stav se nekontroluje"], "note": "", "weak": false},
  {"id": "T3-199", "test": "T3", "set": "T3-tip", "topic": "Výpůjčky přístrojů (přednáška 5)", "q": "Na co je třeba dát pozor při nabíjení baterie TS Trimble M3?", "a": "Baterii netlačit do nabíječky – ulomí se vystřeďovací kolík (nová nabíječka stojí cca 7 tis. Kč).", "wrong": ["Nabíjet jen přes noc", "Nenabíjet na slunci", "Nabíjet jen v přístroji"], "note": "", "weak": false},
  {"id": "T3-200", "test": "T3", "set": "T3-tip", "topic": "Výpůjčky přístrojů (přednáška 5)", "q": "Co zahrnuje přechodné umístění majetku ve výpůjčce?", "a": "Všechna místa, kde bude majetek v průběhu výpůjčky.", "wrong": ["Jen sklad GED", "Jen místo měření", "Adresu bydliště"], "note": "", "weak": false},
  {"id": "T5-001", "test": "T5", "set": "T5-ucitel", "topic": "Test 5", "q": "Uveďte číselně dimenzi modelu, u kterého je výška funkcí souřadnic X a Y.", "a": "2,5D – z = f(x, y), jedna výška na polohu, nelze převisy a jeskyně", "wrong": ["3D – bod může mít více výšek", "2D – jen x, y bez výšky", "4D – navíc čas"], "note": "Model zná ke každé poloze (x, y) jen jednu výšku, jako by se díval jen shora. Proto neumí převis (pod skálou je ještě terén), na to by potřeboval 3D.", "weak": false},
  {"id": "T5-002", "test": "T5", "set": "T5-ucitel", "topic": "Test 5", "q": "Jak se jmenuje digitální model, který obsahuje pouze vrchní plochy terénu (při svislém průmětu)?", "a": "DMP – digitální model povrchu: vrchní plochy včetně objektů (střechy, koruny stromů)", "wrong": ["DMR – čistý reliéf bez objektů", "DVM – pravidelná mřížka výšek", "DMT – reliéf plus objekty, ale i pod střechami"], "note": "DMP je to, co vidíš shora: střechy domů a koruny stromů. Je to výsledek prvního průsečíku paprsku. Podle učitele je to zvláštní případ DMT, ne DMR.", "weak": false},
  {"id": "T5-003", "test": "T5", "set": "T5-ucitel", "topic": "Test 5", "q": "Jak dělíme digitální modely podle toho, jakou část reality reprezentují?", "a": "DMR – reliéf bez objektů; DMP – vrchní plochy; DMT – reliéf + objekty (DMT ≠ DMR)", "wrong": ["DMR – reliéf + objekty; DMT – čistý reliéf; DMP – vrchní plochy", "DMR = DMT = DMP, liší se jen zkratkou", "Rastrový, polyedrický a plátový"], "note": "Představ si les. DMR je holá zem pod ním, DMP jsou koruny stromů a DMT je zem i se stromy jako objekty. Učitel na tom trvá: terén = reliéf + předměty, takže DMT ≠ DMR.", "weak": false},
  {"id": "T5-004", "test": "T5", "set": "T5-ucitel", "topic": "Test 5", "q": "Jak dělíme digitální modely podle modelovací techniky (typu elementárních ploch)?", "a": "Rastrový, polyedrický a plátový", "wrong": ["DMR, DMP a DMT", "2D, 2,5D a 3D", "Hladký, lomový a přímý"], "note": "Rastr je mřížka čtverců (jednoduchá, ale nepřizpůsobí se terénu). Polyedrický model tvoří trojúhelníky přesně v naměřených bodech. Plátový model položí přes trojúhelníky nebo čtverce hladké zakřivené „deky“.", "weak": false},
  {"id": "T5-005", "test": "T5", "set": "T5-ucitel", "topic": "Test 5", "q": "Jak se jmenuje model, který má pouze formu pravidelné mřížky výškových bodů?", "a": "Rastrový model – DVM (DEM), 2,5D, každá buňka mřížky má výšku", "wrong": ["Polyedrický model – TIN", "Plátový model – zakřivené pláty", "DMP – digitální model povrchu"], "note": "DVM je nejjednodušší model: tabulka výšek v pravidelné mřížce. Anglicky DEM.", "weak": false},
  {"id": "T5-006", "test": "T5", "set": "T5-ucitel", "topic": "Test 5", "q": "Jak se jmenuje hrana, nad kterou se při vytváření hladké plochy ve směru kolmém na spojnici nevyhlazuje, ale ve směru podélném se stále vyhlazuje?", "a": "Lomová hrana (L): příčně se nevyhlazuje, podélně ano", "wrong": ["Přímá lomová hrana (R): nevyhlazuje se nikde", "Hladká povinná hrana (P): vyhlazuje se všude", "Ostrovní hrana (O): díra v modelu"], "note": "Vezmi obrubník: přes něj je ostrý skok, ale podél se táhne plynule. Přesně to dělá lomová hrana. Lomová přímá (R) by nevyhlazovala ani podél, to je třeba hrana budovy.", "weak": false},
  {"id": "T5-007", "test": "T5", "set": "T5-ucitel", "topic": "Test 5", "q": "Z čeho je složen plátový model a jak se napojují pláty?", "a": "Zakřivené pláty na rastru nebo polyedru; uzly: regulární bod (společná tečná rovina), zlom (2 roviny), hrot (žádná)", "wrong": ["Rovinné trojúhelníky; uzly: regulární, ostrovní, přímý", "Čtvercová mřížka výšek; uzly: základní, doplňkový, zdůrazněný", "Zakřivené pláty; regulární bod = žádná společná tečná rovina, hrot = jedna"], "note": "Plát je jako ubrus položený na trojúhelník nebo čtverec. V uzlech se sousední pláty buď hladce navazují (regulární bod), nebo se lámou (zlom, třeba hrana stupně), nebo nemají společnou tečnou rovinu (hrot).", "weak": false},
  {"id": "T5-008", "test": "T5", "set": "T5-ucitel", "topic": "Test 5", "q": "Jak se projeví použití povinných spojnic v polyedrickém modelu?", "a": "Strany trojúhelníků leží na spojnici, zlepší se aproximace a zachovají se nespojitosti (ostré hrany, zlomy)", "wrong": ["Model se vyhladí, ostré hrany zmizí", "Zvětší se počet bodů, ale hrany se nezachovají", "Model se převede na rastr s konstantním rozestupem"], "note": "Bez povinné spojnice by trojúhelník mohl „přeskočit“ hranu silnice a model by ji zaoblil. Se spojnicí se trojúhelníky upraví tak, aby hrana byla jejich stranou, a model pak sedí na skutečný terén. Formulace „přeskládání trojúhelníků“ je odvozená, na slajdu doslova není.", "weak": false},
  {"id": "T5-009", "test": "T5", "set": "T5-ucitel", "topic": "Test 5", "q": "Co je veličina označovaná v ČSN 01 3410 jako uH?", "a": "Kritérium pro základní směrodatnou výškovou odchylku σH (uH; 3uH nezpevněný; uv vrstevnice), závisí na třídě přesnosti", "wrong": ["Maximální povolená odchylka jednotlivého bodu", "Výběrová směrodatná odchylka z kontrolních bodů", "Koeficient podle počtu bodů (1,1 nebo 1,0)"], "note": "uH je hranice, kterou nesmí přesáhnout skutečná přesnost výšek σH. Na zpevněném povrchu se dá měřit přesně, takže platí uH. V trávě je terén neurčitý, proto 3·uH. Hodnota se bere podle třídy přesnosti mapy.", "weak": true},
  {"id": "T5-010", "test": "T5", "set": "T5-ucitel", "topic": "Test 5", "q": "K čemu se při testování přesnosti výšek používá koeficient k?", "a": "k = 2 při stejně přesné kontrole, k = 1 při výrazně přesnější (mH < 0,7·uH); ve vzorci sH = √(ΣΔH² / (k·N))", "wrong": ["k = 1 při stejně přesné, k = 2 při výrazně přesnější kontrole", "k je počet kontrolních bodů, minimum 100", "k je hladina významnosti, 5 %"], "note": "Rozdíl ΔH = Hmapa − Hkontrola nese chybu obou určení. Pokud jsou stejně přesná, je v ΔH chyba „dvakrát“, a proto se dělí k = 2. Pokud je kontrola mnohem přesnější (pod 0,7·uH), chyba je prakticky jen v mapě a platí k = 1.", "weak": true},
  {"id": "T5-011", "test": "T5", "set": "T5-tip", "topic": "Test 5", "q": "Co je to terén a z čeho se skládá?", "a": "Terén = terénní reliéf + terénní předměty (objekty)", "wrong": ["Terén = jen terénní reliéf bez objektů", "Terén = jen objekty na povrchu", "Terén = vrchní plochy (první průsečík paprsku)"], "note": "Terén je všechno: kopce i domy, lesy a silnice. Reliéf je jen tvar povrchu, proto terén ≠ reliéf.", "weak": false},
  {"id": "T5-012", "test": "T5", "set": "T5-tip", "topic": "Test 5", "q": "Definujte terénní reliéf.", "a": "Zemský povrch bez objektů, vytvořený přírodními silami nebo uměle; souhrn terénních tvarů", "wrong": ["Zemský povrch včetně budov a vegetace", "Pouze vrstevnice a výškové body", "Povrch vytvořený výhradně přírodními silami"], "note": "Reliéf je holý tvar zemského povrchu, ať ho vytvořila příroda, nebo člověk (třeba násep). Bez domů a stromů.", "weak": false},
  {"id": "T5-013", "test": "T5", "set": "T5-tip", "topic": "Test 5", "q": "Definujte DMR a DMT.", "a": "Digitální reprezentace v paměti počítače: data + interpolační algoritmus pro výšky mezilehlých bodů; DMR reliéf, DMT terén", "wrong": ["Papírová mapa s vrstevnicemi; DMR a DMT jsou totéž", "Seznam souřadnic bez algoritmu; DMR objekty, DMT reliéf", "Pravidelná mřížka výšek; DMR a DMT se liší jen měřítkem"], "note": "Obě definice znějí stejně a liší se jen tím, co popisují: DMR reliéf, DMT terén. Klíčová slova jsou data + interpolační algoritmus → výšky mezilehlých bodů.", "weak": false},
  {"id": "T5-014", "test": "T5", "set": "T5-tip", "topic": "Test 5", "q": "Definujte DVM.", "a": "2,5D rastrový model: výšky v pravidelné mřížce, každá buňka má výšku", "wrong": ["3D model z trojúhelníků (TIN)", "Model zakřivených plátů", "Model vrchních ploch včetně objektů (DMP)"], "note": "DVM je 2,5D rastr: každá buňka mřížky má výšku. Je to spíš název techniky než obsahu. Obvykle popisuje reliéf, takže je to případ DMR.", "weak": false},
  {"id": "T5-015", "test": "T5", "set": "T5-tip", "topic": "Test 5", "q": "Uveďte anglické ekvivalenty zkratek DMR, DMP, DVM.", "a": "DMR = DTM, DMP = DSM, DVM = DEM", "wrong": ["DMR = DSM, DMP = DTM, DVM = DEM", "DMR = DEM, DMP = DTM, DVM = DSM", "DMR = DTM, DMP = DEM, DVM = DSM"], "note": "Pozor na past: anglické DTM je náš DMR, ne DMT. Učitel to zdůrazňuje.", "weak": false},
  {"id": "T5-016", "test": "T5", "set": "T5-tip", "topic": "Test 5", "q": "Popište 2D, 2,5D, 3D a 4D reprezentaci terénu.", "a": "2D: x, y; 2,5D: z = f(x, y); 3D: i převisy a jeskyně; 4D: navíc čas", "wrong": ["2D: x, y, z; 2,5D: dvě výšky; 3D: jen x, y; 4D: barva", "2D: výška; 2,5D: x, y; 3D: čas; 4D: převisy", "2D: mapa; 2,5D: stejná jako 3D; 3D a 4D neexistují"], "note": "2D je jen polohopis. 2,5D má výšku jako atribut (jedna výška na bod). 3D umí cokoli včetně převisů, protože používá parametrické rovnice. 4D přidá čas.", "weak": false},
  {"id": "T5-017", "test": "T5", "set": "T5-tip", "topic": "Test 5", "q": "Co jsou singularity v DMT a jak se řeší?", "a": "Místa, kde běžná interpolace selže (ostré hrany, zlomy, převisy, vodorovná tečná rovina); řeší se povinnými spojnicemi", "wrong": ["Chybné body měření; řeší se jejich smazáním", "Body mimo území modelu; řeší se zvětšením území", "Přebytečné body rastru; řeší se zvětšením kroku mřížky"], "note": "Singularity jsou místa, kde funkce terénu není hladká nebo spojitá. Model by je zaoblil nebo pokazil, proto se do něj přidají povinné spojnice.", "weak": false},
  {"id": "T5-018", "test": "T5", "set": "T5-tip", "topic": "Test 5", "q": "Jaké jsou vlastnosti polyedrického modelu?", "a": "Nepravidelné trojúhelníky, lineární interpolace, hustota podle členitosti, lépe aproximuje než rastr, i nekonvexní území s otvory", "wrong": ["Pravidelná čtvercová mřížka, konstantní rozestupy", "Zakřivené pláty, nelineární interpolace, nejsložitější", "Jen obdélníkové území bez otvorů"], "note": "Trojúhelníky sedí přesně na naměřených bodech a v členitém terénu jich může být víc. Díky tomu aproximuje terén lépe než rastr.", "weak": false},
  {"id": "T5-019", "test": "T5", "set": "T5-tip", "topic": "Test 5", "q": "Co je TIN a z čeho se skládá jeho struktura?", "a": "Vektorový popis polyedrického modelu s topologií: seznam souřadnic vrcholů, vrcholů trojúhelníků a sousedních trojúhelníků", "wrong": ["Rastrový popis: seznam výšek buněk mřížky", "Seznam hran a seznam priorit hran", "Seznam vrstevnic a seznam kót"], "note": "TIN si pamatuje, kde jsou vrcholy, které vrcholy tvoří který trojúhelník a kdo s kým sousedí. Díky tomu rychle najde sousední trojúhelníky.", "weak": true},
  {"id": "T5-020", "test": "T5", "set": "T5-tip", "topic": "Test 5", "q": "Jaké jsou vlastnosti rastrového modelu?", "a": "Konstantní rozestupy, snadné výpočty, nepřizpůsobí se terénu, většinou horší než polyedrický, obdélníkové území", "wrong": ["Hustota podle členitosti, nekonvexní území s otvory", "Zakřivené pláty, plynulé napojení v uzlech", "Nepravidelné trojúhelníky, lépe vystihne terén než polyedrický"], "note": "Mřížka se snadno počítá, ale je „hloupá“: v rovině má zbytečně bodů, na hraně jich má málo. Proto obvykle dává horší výsledky než trojúhelníky.", "weak": false},
  {"id": "T5-021", "test": "T5", "set": "T5-tip", "topic": "Test 5", "q": "Jaký je rozdíl mezi lineární a nelineární (morfologickou) interpolací?", "a": "Lineární: výška po přímce (konstantní spád); nelineární (morfologická): po křivce, plynulá změna sklonu", "wrong": ["Lineární: po křivce; nelineární: po přímce", "Lineární patří k plátovému modelu, nelineární k rastrovému", "Rozdíl je jen v počtu kontrolních bodů"], "note": "Lineární interpolace si myslí, že mezi body je rovná plocha, takže vrstevnice jsou rovnoměrně od sebe. Morfologická respektuje tvar okolí (vypouklý a vhloubený svah), takže je věrnější, ale složitější na výpočet.", "weak": true},
  {"id": "T5-022", "test": "T5", "set": "T5-tip", "topic": "Test 5", "q": "Charakterizujte hladké, lomové a přímé hrany a uveďte použití.", "a": "P: vyhlazuje se všude; L: příčně ne, podélně ano; R: nikde (budovy); O, U: ostrovní, díry v modelu", "wrong": ["P: nevyhlazuje se nikde; L: všude; R: podélně ano", "P: ostrovní; L: povinná; R: lomová; O: přímá", "L: nevyhlazuje se nikde (budovy); R: podélně ano (silnice)"], "note": "Zapamatuj si to podle toho, kde se vyhlazuje: hladká všude, lomová jen podél (obrubník), přímá nikde (hrana budovy). Ostrovní hrany ohraničují díry v modelu.", "weak": true},
  {"id": "T5-023", "test": "T5", "set": "T5-tip", "topic": "Test 5", "q": "Co je priorita hrany?", "a": "Číslo 1–255; při křížení hran zůstane hrana s vyšší prioritou", "wrong": ["Číslo 0–100; zůstane hrana s nižší prioritou", "Číslo 1–255; hrany se při křížení obě zruší", "Pořadí měření hran; zůstane hrana měřená dříve"], "note": "Když se dvě povinné spojnice kříží, model nemůže zachovat obě. Zůstane ta s vyšší prioritou.", "weak": true},
  {"id": "T5-024", "test": "T5", "set": "T5-tip", "topic": "Test 5", "q": "Jaký je rozdíl mezi běžnými a povinnými body a mezi měkkými a tvrdými zlomy?", "a": "Běžné body model použít nemusí, povinné jsou vrcholy trojúhelníků; měkký zlom hladkost nezlomí (zaoblený), tvrdý ano (ostrý)", "wrong": ["Běžné body jsou kontrolní, povinné změřené; měkký zlom je zaoblený, tvrdý ne", "Běžné jsou body bodového pole, povinné podrobné; měkký a tvrdý zlom jsou totéž", "Povinné body se vyřadí, běžné ne; tvrdý zlom je zaoblený, měkký ostrý"], "note": "Běžné body jsou „náplň“, kterou může optimalizace vyřadit. Povinné body (vrcholy, sedla) zůstat musí. Měkký zlom TIN obsahuje, ale povrch na něm zůstane hladký. Tvrdý zlom ho ostře zlomí.", "weak": true},
  {"id": "T5-025", "test": "T5", "set": "T5-tip", "topic": "Test 5", "q": "Jak vypadá plátový model nad polyedrickým a nad rastrovým modelem?", "a": "Nad polyedrickým trojúhelníkové pláty, nad rastrovým čtvercové; složitější výpočty", "wrong": ["Nad polyedrickým čtvercové, nad rastrovým trojúhelníkové", "Nad oběma stejné pláty; jednodušší výpočty než rastr", "Plátový model nelze nad rastrem použít"], "note": "Plát kopíruje tvar plošky, na kterou ho položíš: nad trojúhelníky jsou trojúhelníkové, nad mřížkou čtvercové.", "weak": false},
  {"id": "T5-026", "test": "T5", "set": "T5-tip", "topic": "Test 5", "q": "Jaké jsou typy uzlových bodů plátů?", "a": "Regulární bod (společná tečná rovina), zlom (2 roviny), hrot (žádná společná rovina)", "wrong": ["Regulární bod (žádná), zlom (1), hrot (2)", "Základní, zdůrazněný, doplňkový", "Hladký, lomový, ostrovní"], "note": "Regulární bod: jedna společná tečná rovina, takže hladký přechod. Zlom: dvě tečné roviny, ostrý přechod. Hrot: žádná společná tečná rovina, model se nezaoblí.", "weak": false},
  {"id": "T5-027", "test": "T5", "set": "T5-tip", "topic": "Test 5", "q": "Kdy a jak se ověřuje přesnost podle ČSN 01 3410?", "a": "Průběžně i závěrečně; test hypotézy na výběru bodů, hladina významnosti α = 5 %", "wrong": ["Jen na konci; porovnáním s mapou, α = 1 %", "Jen průběžně; metodou nejmenších čtverců, α = 10 %", "Jen při zadání zakázky; výběr 10 bodů, α = 5 %"], "note": "Přesnost se kontroluje průběžně během tvorby i na konci. Testuje se statistická hypotéza, že výběr bodů patří do stanovené třídy přesnosti, u účelových map základního významu na hladině 5 %.", "weak": false},
  {"id": "T5-028", "test": "T5", "set": "T5-tip", "topic": "Test 5", "q": "Podle jakých 4 podmínek se vyberou body pro testování přesnosti?", "a": "Jednoznačně identifikovatelné, reprezentativní (min. 100), rovnoměrně rozmístěné, ne v blízkosti bodů použitých při tvorbě", "wrong": ["Časově stálé, nezávisle změřené, min. 10, na hranici území", "Jen body bodového pole, min. 100, shluky v členitém terénu", "Jednoznačně identifikovatelné, min. 30, jen na zpevněném povrchu"], "note": "Body musí jít v terénu bezpečně najít, musí jich být dost (nejméně 100), musí pokrýt celé území a nesmí ležet hned u bodů bodového pole, ze kterých se měřilo (ty by vyšly uměle přesně).", "weak": false},
  {"id": "T5-029", "test": "T5", "set": "T5-tip", "topic": "Test 5", "q": "Co je jednoznačně identifikovatelný bod?", "a": "Polohu lze opakovaně identifikovat s odchylkou ≤ čtvrtina uxy (2. třída 0,02 m)", "wrong": ["Leží na průsečíku dvou přímek pod úhlem 60–120°", "Odchylka ≤ 0,7·uxy", "Odchylka ≤ dvojnásobek uxy"], "note": "Bod musí jít v terénu najít znovu a vždy na stejném místě, s přesností lepší než čtvrtina kritéria uxy. Pro 2. třídu je to 0,02 m.", "weak": true},
  {"id": "T5-030", "test": "T5", "set": "T5-tip", "topic": "Test 5", "q": "Jaké dvě podmínky musí být splněny, aby byla přesnost určení výšek vyhovující?", "a": "ΔH ≤ 2·uH·k a sH ≤ ωN·uH (nezpevněný 3·ωN·uH; vrstevnice ωN·uv)", "wrong": ["ΔH ≤ uH a σH ≤ ωN·uH", "ΔH ≤ 2·uH a sH ≤ k·uH", "sH ≤ 2·uH·k a ΔH ≤ ωN·uH"], "note": "Žádný rozdíl nesmí být hrubá chyba (ΔH ≤ 2·uH·k) a celková výběrová odchylka sH se musí vejít do kritéria podle povrchu.", "weak": true},
  {"id": "T5-031", "test": "T5", "set": "T5-tip2", "topic": "Test 5", "q": "Proč podle učitele neplatí, že DMT = DMR?", "a": "Terén = terénní reliéf + terénní předměty, tedy terén ≠ reliéf, a proto DMT ≠ DMR", "wrong": ["Protože DMT je rastrový a DMR polyedrický", "Protože DMR je 3D a DMT 2,5D", "Protože DMT je anglicky DTM a DMR DEM"], "note": "Definice VÚGTK (DMR = DMT) učitel považuje za nekorektní.", "weak": false},
  {"id": "T5-032", "test": "T5", "set": "T5-tip2", "topic": "Test 5", "q": "Proč je DMP podle učitele zvláštní případ DMT, a ne DMR?", "a": "Protože DMP reprezentuje terén (vrchní plochy včetně objektů), nikoli pouze reliéf", "wrong": ["Protože DMP neobsahuje žádné objekty", "Protože DMP je vždy rastrový", "Protože DMP vzniká jen ruční vektorizací"], "note": "Upravená definice: DMP zobrazuje pouze vrchní (vnější) plochy terénu včetně objektů.", "weak": false},
  {"id": "T5-033", "test": "T5", "set": "T5-tip2", "topic": "Test 5", "q": "Jak se DMP zpravidla konstruuje?", "a": "Automatickými prostředky (např. obrazovou korelací ve fotogrammetrii); je výsledkem prvního průsečíku promítacího paprsku", "wrong": ["Ručním zaměřením bodů terénní kostry tachymetrií", "Interpolací z vrstevnic", "Plošnou nivelací ve čtvercové síti"], "note": "Proto obsahuje střechy, koruny stromů apod.", "weak": false},
  {"id": "T5-034", "test": "T5", "set": "T5-tip2", "topic": "Test 5", "q": "Čím se liší 3D reprezentace terénu od 2,5D?", "a": "Plochy se vyjadřují parametrickými rovnicemi (x = f(u,v), y = g(u,v), z = h(u,v)); k bodu (x, y) může existovat více z", "wrong": ["3D používá explicitní rovnici z = f(x, y)", "3D přidává čas", "3D neobsahuje souřadnici z"], "note": "Tak lze vyjádřit téměř libovolné tvary terénu, i převisy a jeskyně.", "weak": false},
  {"id": "T5-035", "test": "T5", "set": "T5-tip2", "topic": "Test 5", "q": "Proč je modelování terénu obtížné?", "a": "V místech singularit je funkce či její derivace nespojitá; terén je rozsáhlý ve směru x, y a má malý rozsah z", "wrong": ["Protože body nemají souřadnice", "Protože terén nelze vůbec zaměřit", "Protože rastrový model nejde spočítat"], "note": "Singularity se řeší povinnými spojnicemi.", "weak": false},
  {"id": "T5-036", "test": "T5", "set": "T5-tip2", "topic": "Test 5", "q": "Jak vzniká polyedr v polyedrickém modelu?", "a": "Proložením rovin vrcholy nepravidelných trojúhelníků vznikne nepravidelný mnohostěn, který se přimyká k terénu", "wrong": ["Proložením zakřivených plátů přes čtverce", "Sjednocením buněk pravidelné mřížky", "Spojením vrstevnic do uzavřených křivek"], "note": "Sousední trojúhelníky mají společnou nejvýše hranu; síť se tvoří triangulačními algoritmy.", "weak": false},
  {"id": "T5-037", "test": "T5", "set": "T5-tip2", "topic": "Test 5", "q": "K čemu je výhodná topologie v TIN?", "a": "Umožňuje efektivní výběr sousedních trojúhelníků a urychluje geometrické i topologické operace nad modelem", "wrong": ["Zmenšuje počet bodů na polovinu", "Převádí model automaticky na rastr", "Odstraňuje potřebu povinných hran"], "note": "TIN = vektorový popis polyedrického modelu se zavedením topologických vztahů mezi trojúhelníky.", "weak": false},
  {"id": "T5-038", "test": "T5", "set": "T5-tip2", "topic": "Test 5", "q": "Co představují plošky rastrového modelu?", "a": "Zborcené čtyřúhelníky (grid), které lze rozdělit na trojúhelníky", "wrong": ["Nepravidelné trojúhelníky", "Zakřivené pláty", "Vrstevnicové pásy"], "note": "Plošky jsou pravidelné a mají společné hrany.", "weak": false},
  {"id": "T5-039", "test": "T5", "set": "T5-tip2", "topic": "Test 5", "q": "Jak se v rastrovém modelu řeší nekonvexní území?", "a": "Musí se složit z několika konvexních (obdélníkových) oblastí", "wrong": ["Rastr nekonvexní území zvládne sám", "Doplní se ostrovními hranami", "Přepne se na 3D reprezentaci"], "note": "Území rastrového modelu má tvar obdélníka (konvexní).", "weak": false},
  {"id": "T5-040", "test": "T5", "set": "T5-tip2", "topic": "Test 5", "q": "Proč se používá plátový model?", "a": "Rastrový i polyedrický mají mezi ploškami ostré přechody (nepůsobí přirozeně); plátový model může být hladký", "wrong": ["Protože je výpočetně nejjednodušší", "Protože nepotřebuje žádná data", "Protože jako jediný umí převisy"], "note": "Vyhlazuje model v místech, kde je hladký i původní terén. Nevýhoda: složitější výpočty.", "weak": false},
  {"id": "T5-041", "test": "T5", "set": "T5-tip2", "topic": "Test 5", "q": "Jak se zajistí hladké napojení plátů v uzlovém bodě?", "a": "Z incidujících trojúhelníků se spočítá průměrný normálový vektor, určí se tečná rovina a uzlové body se volí v ní", "wrong": ["Uzlové body se posunou do průměrné výšky okolí", "Pláty se spojí povinnou lomovou hranou", "Uzlový bod se z modelu vyřadí"], "note": "V regulárním bodě pak existuje společná tečná rovina.", "weak": false},
  {"id": "T5-042", "test": "T5", "set": "T5-tip2", "topic": "Test 5", "q": "Čím se liší ostrovní hrana O od ostrovní hrany U?", "a": "O je lomová ve smyslu L, U je lomová přímá ve smyslu R; obě označují okraj ostrova, kde se nevyhodnocují vrstevnice", "wrong": ["O je hladká, U je lomová", "O označuje díru, U ostrov s vrstevnicemi", "O se používá jen v rastru, U jen v TIN"], "note": "Ostrovní hrany = díry v modelu (nemodelované části území).", "weak": false},
  {"id": "T5-043", "test": "T5", "set": "T5-tip2", "topic": "Test 5", "q": "K čemu se používá povinná (hladká) hrana P?", "a": "Pro hřbetnice a údolnice s plynulým stykem ploch, pro polohopisnou kresbu (ploty, hranice) a pro zlepšení tvaru trojúhelníků", "wrong": ["Pro hrany budov a mostních pilířů", "Pro okraj ostrova bez vrstevnic", "Pro meze a okraje vozovek"], "note": "Nad hranou P se terén stále vyhlazuje, nezpůsobuje změnu ve vyhlazení.", "weak": false},
  {"id": "T5-044", "test": "T5", "set": "T5-tip2", "topic": "Test 5", "q": "Jak se v Atlas DMT předepisují povinné hrany?", "a": "Jako sekvence bodů tvořící řetěz spojnic; řádka začíná znakem „.“ a znakem typu (P, L, R, O, U)", "wrong": ["Každá hrana zvlášť dvojicí souřadnic", "Kódem v zápisníku u každého bodu zvlášť", "Nakreslením v rastru"], "note": "Význam znaků: P povinná, L lomová, R přímá lomová, O ostrovní lomová, U ostrovní přímá.", "weak": false},
  {"id": "T5-045", "test": "T5", "set": "T5-tip2", "topic": "Test 5", "q": "Jaký je ve 3D modelu TIN rozdíl mezi tupými a ostrými zlomy?", "a": "Žádný – v hraně musí jen ležet strany trojúhelníků; rozdíl se projeví v plátovém modelu nebo při interpolaci TIN do GRID", "wrong": ["Ostré zlomy mají vyšší prioritu", "Tupé zlomy se do TIN nezadávají", "Ostré zlomy vytvoří díru v modelu"], "note": "Příčná derivace ostrých hran je nulová – interpolovaný GRID pak obsahuje zlomovou hranu.", "weak": false},
  {"id": "T5-046", "test": "T5", "set": "T5-tip2", "topic": "Test 5", "q": "Jaké vrstevnice se z TIN vytvářejí jako konečný výstup?", "a": "Vždy finální hladké vrstevnice (s dělením trojúhelníků sítě)", "wrong": ["Pracovní lomené vrstevnice bez dělení trojúhelníků", "Pomocné vrstevnice 9.06", "Žádné, výstupem je jen hypsometrie"], "note": "Model TIN se generuje na základě definovaných povinných hran; pak následují vizuální kontroly a korektury.", "weak": false},
  {"id": "T5-047", "test": "T5", "set": "T5-tip2", "topic": "Test 5", "q": "Co je podle ČSN 01 3410 kritérium přesnosti?", "a": "Kritická hodnota charakteristiky přesnosti", "wrong": ["Průměr naměřených odchylek", "Počet kontrolních bodů", "Hladina významnosti testu"], "note": "Např. σH je charakteristika, uH je její kritérium.", "weak": false},
  {"id": "T5-048", "test": "T5", "set": "T5-tip2", "topic": "Test 5", "q": "Jak se při testování výšek počítá rozdíl ΔH?", "a": "ΔH = Hm − Hk (výška v mapě minus výška z kontrolního určení)", "wrong": ["ΔH = Hk − Hm", "ΔH = (Hm + Hk) / 2", "ΔH = Hm − uH"], "note": "Ze všech ΔH výběru se pak počítá sH.", "weak": false},
  {"id": "T5-049", "test": "T5", "set": "T5-tip2", "topic": "Test 5", "q": "Jakou hodnotu má koeficient ωN při α = 5 %?", "a": "1,1 pro výběr 80 až 500 bodů, 1,0 pro výběr větší než 500 bodů", "wrong": ["1,1 pro 100–300 bodů, 1,0 nad 300", "2 pro stejně přesné, 1 pro přesnější kontrolu", "0,7 pro všechny výběry"], "note": "Pozor: 100–300 / nad 300 platí pro ω2N u souřadnic, ne pro výšky.", "weak": false},
  {"id": "T5-050", "test": "T5", "set": "T5-tip2", "topic": "Test 5", "q": "Proč se přesnost mapy průběžně a závěrečně ověřuje?", "a": "Aby se odhalily a odstranily systematické nebo hrubé chyby", "wrong": ["Aby se zvýšila třída přesnosti mapy", "Aby se snížil počet podrobných bodů", "Aby se určil koeficient k"], "note": "Pro polohopis se kontroluje rozdíly délek nebo souřadnic, pro výškopis rozdíly výšek.", "weak": false},
];
